    function toggleSettings(tid, kind = 'main') {
        let el = document.getElementById(getPrototypePanelId(tid, kind));
        if (el) el.style.display = (el.style.display === 'grid') ? 'none' : 'grid';
    }

    function toggleAllProtos(tid, checked, kind = 'main') {
        const data = getPrototypeData(tid, kind);
        if (!data || !data.prototypes) return;

        data.prototypes.forEach((p, idx) => {
            const cb = document.getElementById(getPrototypeCheckboxId(tid, idx, kind));
            if (cb) cb.checked = checked;
        });

        const master = document.getElementById(getPrototypeMasterId(tid, kind));
        if (master) {
            master.checked = checked;
            master.indeterminate = false;
        }
    }

    function syncProtoMaster(tid, kind = 'main') {
        const data = getPrototypeData(tid, kind);
        const master = document.getElementById(getPrototypeMasterId(tid, kind));
        if (!data || !data.prototypes || !master) return;

        const boxes = data.prototypes
            .map((p, idx) => document.getElementById(getPrototypeCheckboxId(tid, idx, kind)))
            .filter(Boolean);

        const checkedCount = boxes.filter(cb => cb.checked).length;
        master.checked = checkedCount === boxes.length;
        master.indeterminate = checkedCount > 0 && checkedCount < boxes.length;
    }


    function getTaskCountTarget(input) {
        const key = input.id.slice('count-'.length);
        const kind = key.startsWith('extra-') ? 'extra' : 'main';
        const tid = kind === 'extra' ? key.slice('extra-'.length) : key;
        return { tid, kind };
    }

    function updateTaskTotal() {
        let total = 0;
        document.querySelectorAll('input[id^="count-"]').forEach(input => {
            let value = parseInt(input.value, 10);
            const previousCount = parseInt(input.dataset.previousCount, 10) || 0;
            if (!isNaN(value) && value > 0) {
                total += value;
                if (previousCount <= 0) {
                    const { tid, kind } = getTaskCountTarget(input);
                    const data = getPrototypeData(tid, kind);
                    const hasSelection = data && Array.isArray(data.prototypes) && data.prototypes.some((p, idx) => {
                        const checkbox = document.getElementById(getPrototypeCheckboxId(tid, idx, kind));
                        return checkbox && checkbox.checked;
                    });
                    if (!hasSelection) toggleAllProtos(tid, true, kind);
                }
            }
            input.dataset.previousCount = !isNaN(value) && value > 0 ? String(value) : '0';
        });

        let totalEl = document.getElementById('task-total-count');
        if (totalEl) totalEl.textContent = total;
    }

    function adjustTaskCount(tid, delta, event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        const input = document.getElementById(`count-${tid}`);
        if (!input) return;

        let value = parseInt(input.value, 10);
        if (isNaN(value)) value = 0;

        value += delta;
        if (value < 0) value = 0;

        input.value = value;
        updateTaskTotal();
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
    }

    window.randomVariantMode = false;
    window.randomVariantPicks = null;
    window.randomVariantNumber = null;
    // Текущий план ручного варианта. Нужен для точечной замены одной задачи
    // без пересборки остальных заданий. Каждый элемент хранит номер задания,
    // источник (main/extra), прототип и конкретный аналог внутри прототипа.
    window.manualVariantPlan = null;

    function getCurrentVariantTitle() {
        return window.randomVariantMode && window.randomVariantNumber
            ? `Вариант №${window.randomVariantNumber}`
            : 'Тренировочный вариант';
    }

    function getRandomTaskPick(tid, avoidPick = null) {
        const data = window.database && window.database[tid];
        if (!data || !Array.isArray(data.prototypes)) return null;

        const protos = data.prototypes
            .map((p, protoIndex) => ({ p, protoIndex }))
            .filter(x => x.p && Array.isArray(x.p.tasks) && x.p.tasks.length > 0);
        if (!protos.length) return null;

        const makePick = () => {
            const proto = protos[Math.floor(Math.random() * protos.length)];
            const taskIndex = Math.floor(Math.random() * proto.p.tasks.length);
            const task = proto.p.tasks[taskIndex];
            return {
                protoIndex: proto.protoIndex,
                taskIndex,
                taskKey: String(task && (task.id ?? task.text ?? taskIndex))
            };
        };

        // При замене стараемся действительно получить другую задачу.
        for (let attempt = 0; attempt < 40; attempt++) {
            const pick = makePick();
            if (!avoidPick || pick.protoIndex !== avoidPick.protoIndex || pick.taskKey !== avoidPick.taskKey) return pick;
        }

        const all = [];
        protos.forEach(({p, protoIndex}) => p.tasks.forEach((task, taskIndex) => {
            const pick = { protoIndex, taskIndex, taskKey: String(task && (task.id ?? task.text ?? taskIndex)) };
            if (!avoidPick || pick.protoIndex !== avoidPick.protoIndex || pick.taskKey !== avoidPick.taskKey) all.push(pick);
        }));
        return all.length ? all[Math.floor(Math.random() * all.length)] : makePick();
    }

    function buildRandomVariantPicks() {
        const picks = {};
        const missing = [];
        for (let n = 1; n <= 20; n++) {
            const tid = `task${n}`;
            const pick = getRandomTaskPick(tid);
            if (pick) picks[tid] = pick;
            else missing.push(n);
        }
        return { picks, missing };
    }

    function setRandomVariantButtonsVisible(visible) {
        const reroll = document.getElementById('random-reroll-btn');
        const answers = document.getElementById('random-answers-btn');
        const box = document.getElementById('random-inline-answers');
        if (reroll) reroll.style.display = visible ? '' : 'none';
        if (answers) {
            answers.style.display = visible ? '' : 'none';
            answers.textContent = '🔑 Показать ответы';
        }
        if (box) {
            box.style.display = 'none';
            box.innerHTML = '';
        }
    }

    function generateRandomVariant(event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }
        const infoBoard = document.getElementById('info-board');
        const btn = event && event.currentTarget ? event.currentTarget : null;
        if (btn) {
            btn.disabled = true;
            btn.dataset.oldText = btn.textContent;
            btn.textContent = '🎲 Собираю вариант...';
        }

        setTimeout(() => {
            try {
                const result = buildRandomVariantPicks();
                if (result.missing.length) {
                    throw new Error(`Не загружена база заданий: ${result.missing.join(', ')}. Проверьте файлы task1.js–task20.js рядом с index.html.`);
                }
                window.randomVariantPicks = result.picks;
                window.randomVariantMode = true;
                window.randomVariantNumber = Math.floor(1000 + Math.random() * 9000);
                generateVariant({ useRandomPicks: true });
                const output = document.getElementById('output-section');
                if (output) output.scrollIntoView({ behavior: 'smooth', block: 'start' });
            } catch (err) {
                console.error(err);
                if (infoBoard) {
                    infoBoard.style.display = 'block';
                    infoBoard.innerHTML = '<b>Не удалось собрать случайный вариант:</b> ' + (err && err.message ? err.message : err);
                }
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.textContent = btn.dataset.oldText || '🎲 Сгенерировать случайный вариант';
                }
            }
        }, 0);
    }

    function getVariantReplacementPrototypes(tid, kind, protoIndex, mode, selectedOnly = false) {
        const data = getPrototypeData(tid, kind);
        if (!data || !Array.isArray(data.prototypes)) return [];
        return data.prototypes.map((proto,index)=>({proto,protoIndex:index})).filter(entry=>{
            if (!Array.isArray(entry.proto?.tasks) || !entry.proto.tasks.some(Boolean)) return false;
            if (mode === 'inside') return entry.protoIndex === protoIndex;
            if (mode !== 'type' || entry.protoIndex === protoIndex) return false;
            return !selectedOnly || document.getElementById(getPrototypeCheckboxId(tid,entry.protoIndex,kind))?.checked;
        });
    }

    function sameVariantTaskContent(first, second) {
        if (!first || !second) return first === second;
        return ['text','answer','svg_code','imageHTML'].every(field=>String(first[field]??'') === String(second[field]??''));
    }

    function getVariantReplacementPick({tid, kind = 'main', current, mode, selectedOnly = false, otherPicks = []}) {
        const prototypes = getVariantReplacementPrototypes(tid,kind,current.protoIndex,mode,selectedOnly);
        const usedPrototypes = new Set(otherPicks.map(pick=>pick.protoIndex));
        const freshPrototypes = prototypes.filter(entry=>!usedPrototypes.has(entry.protoIndex));
        const pool = freshPrototypes.length ? freshPrototypes : prototypes;
        if (!pool.length) return null;
        const chosen = pool[Math.floor(Math.random()*pool.length)];
        // Индексы различают графические аналоги с одинаковыми условием и ответом.
        const currentTask = chosen.proto.tasks[current.taskIndex];
        const tasks = chosen.proto.tasks.map((task,taskIndex)=>({task,taskIndex})).filter(entry=>
            entry.task && (chosen.protoIndex !== current.protoIndex ||
                (entry.taskIndex !== current.taskIndex && !sameVariantTaskContent(entry.task,currentTask))));
        const usedTasks = new Set(otherPicks.filter(pick=>pick.protoIndex===chosen.protoIndex).map(pick=>pick.taskIndex));
        const freshTasks = tasks.filter(entry=>!usedTasks.has(entry.taskIndex));
        const candidates = freshTasks.length ? freshTasks : tasks;
        if (!candidates.length) return null;
        const next = candidates[Math.floor(Math.random()*candidates.length)];
        return {protoIndex:chosen.protoIndex,taskIndex:next.taskIndex,
            taskKey:String(next.task.id ?? next.task.text ?? next.taskIndex)};
    }

    function buildVariantReplacementButtons(tid, kind, item, planIndex, random) {
        const protoIndex = item.protoIndex;
        const inside = getVariantReplacementPrototypes(tid,kind,protoIndex,'inside').some(entry=>
            entry.proto.tasks.some((task,index)=>task && index !== item.sourceTaskIndex &&
                !sameVariantTaskContent(task,entry.proto.tasks[item.sourceTaskIndex])));
        const type = getVariantReplacementPrototypes(tid,kind,protoIndex,'type',!random).length > 0;
        const handler = random ? `replaceRandomVariantTask('${tid}',` : `replaceManualVariantTask(${planIndex},`;
        const controls = [
            inside ? `<button type="button" class="random-replace-btn" onclick="${handler}'inside')" title="Другой числовой аналог того же типа; остальные задания сохраняются">🔄 Заменить внутри типа</button>` : '',
            type ? `<button type="button" class="random-replace-btn ege-replace-type-btn" onclick="${handler}'type')" title="Другой прототип этого номера; остальные задания сохраняются">↔ Заменить тип</button>` : ''
        ].join('');
        return controls ? `<div class="ege-replace-bar">${controls}</div>` : '';
    }

    function replaceRandomVariantTask(tid, mode = 'inside') {
        if (!window.randomVariantMode || !window.randomVariantPicks || !window.randomVariantPicks[tid]) return;
        const oldPick = window.randomVariantPicks[tid];
        const otherPicks = (window.egeVariantBatch || [])
            .filter((entry,index)=>index !== (window.egeActiveVariantIndex || 0))
            .map(entry=>entry.picks?.[tid]).filter(Boolean);
        const nextPick = getVariantReplacementPick({tid,current:oldPick,mode,otherPicks});
        if (!nextPick) return;
        window.randomVariantPicks[tid] = nextPick;
        generateVariant({ useRandomPicks: true });
        const num = parseInt(String(tid).replace(/\D/g, ''), 10);
        requestAnimationFrame(() => {
            const el = document.querySelector(`.generated-task-block[data-random-task-number="${num}"]`);
            if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        });
    }


    function replaceManualVariantTask(planIndex, mode = 'inside') {
        const plan = Array.isArray(window.manualVariantPlan) ? window.manualVariantPlan : null;
        const current = plan && plan[planIndex];
        if (!current) return;

        const kind = current.kind || 'main';
        const otherPicks = plan.filter((pick,index)=>index !== planIndex && pick.tid === current.tid && (pick.kind || 'main') === kind);
        const next = getVariantReplacementPick({tid:current.tid,kind,current,mode,selectedOnly:true,otherPicks});
        if (!next) {
            alert(mode === 'type' ? 'Для замены типа отметьте другие прототипы этого задания в настройках.' : 'В этом прототипе нет другого загруженного варианта задачи.');
            return;
        }

        const nextPlan = plan.map((item, idx) => idx === planIndex ? {
            ...item,
            protoIndex: next.protoIndex,
            taskIndex: next.taskIndex,
            taskKey: next.taskKey
        } : { ...item });

        window.manualVariantPlan = nextPlan;
        generateVariant({ manualPlan: nextPlan });

        requestAnimationFrame(() => {
            const el = document.querySelector(`.generated-task-block[data-manual-plan-index="${planIndex}"]`);
            if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        });
    }

    function toggleRandomVariantAnswers() {
        if (!window.randomVariantMode) return;
        const box = document.getElementById('random-inline-answers');
        const btn = document.getElementById('random-answers-btn');
        if (!box || !btn) return;
        const opening = box.style.display === 'none' || !box.style.display;
        if (opening) {
            box.innerHTML = `<h3 style="margin-top:0;color:#7b1fa2;">Ответы к ${getCurrentVariantTitle().toLowerCase()}</h3>${currentAnswersHTML}`;
            box.style.display = 'block';
            btn.textContent = '🙈 Скрыть ответы';
            if (window.MathJax) MathJax.typesetPromise([box]).catch(() => {});
        } else {
            box.style.display = 'none';
            btn.textContent = '🔑 Показать ответы';
        }
    }

    function safeGenerateVariant(event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        const btn = event && event.currentTarget ? event.currentTarget : document.querySelector('.btn-generate');
        const infoBoard = document.getElementById('info-board');

        if (btn) {
            btn.disabled = true;
            btn.dataset.oldText = btn.textContent;
            btn.textContent = 'Генерирую...';
        }

        setTimeout(() => {
            try {
                generateVariant({ useRandomPicks: false });
            } catch (err) {
                console.error(err);
                if (infoBoard) {
                    infoBoard.style.display = 'block';
                    infoBoard.innerHTML = '<b>Ошибка при повторной генерации:</b> ' + (err && err.message ? err.message : err);
                }
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.textContent = btn.dataset.oldText || 'Сгенерировать вариант';
                }
            }
        }, 0);
    }

    function scrollToGenerationArea() {
        const target = document.getElementById('generation-controls');
        if (!target) return;

        const stickyPanel = document.getElementById('task-total-panel');
        const stickyHeight = stickyPanel ? stickyPanel.offsetHeight : 0;
        const targetTop = target.getBoundingClientRect().top + window.pageYOffset;
        const top = Math.max(0, targetTop - stickyHeight - 18);

        window.scrollTo({ top, behavior: 'smooth' });
    }

    function resetTaskCounts() {
        if (typeof window.egeResetVariants === 'function') window.egeResetVariants();
        document.querySelectorAll('input[id^="count-"]').forEach(input => {
            input.value = 0;
        });

        document.querySelectorAll('#dynamic-tasks input[type="checkbox"]').forEach(input => {
            input.checked = false;
            input.indeterminate = false;
        });

        window.randomVariantMode = false;
        window.randomVariantPicks = null;
        window.randomVariantNumber = null;
        window.manualVariantPlan = null;
        window.currentGeneratedTasks = [];
        window.selectedBlockTitles = [];
        window.mainCanvases = {};
        currentInteractiveHTML = '';
        currentPrintHTML = '';
        currentAnswersHTML = '';
        setRandomVariantButtonsVisible(false);

        ['output-section', 'info-board', 'ege-variant-switch'].forEach(id => {
            const element = document.getElementById(id);
            if (element) {
                element.innerHTML = '';
                element.style.display = 'none';
            }
        });
        const buttons = document.getElementById('btn-group');
        if (buttons) buttons.style.display = 'none';
        hideTooltip();

        updateTaskTotal();

        let note = document.getElementById('task-total-note');
        if (note) {
            note.style.display = 'block';
            clearTimeout(window.taskTotalNoteTimer);
            window.taskTotalNoteTimer = setTimeout(() => {
                note.style.display = 'none';
            }, 1800);
        }
    }


    const tooltip = document.getElementById('proto-tooltip');
    function showTooltip(tid, index, e, kind = 'main') {
        let data = getPrototypeData(tid, kind);
        if (!data || !data.prototypes || !data.prototypes[index]) return;
        let p = data.prototypes[index];
        tooltip.innerHTML = `${p.svg_code || ''}<div style="font-size: 0.9em;">${p.tasks[0].text}</div>`;
        if (window.autoFixSVGArrows) window.autoFixSVGArrows(tooltip);
        tooltip.style.display = 'block';
        if (window.MathJax) MathJax.typesetPromise([tooltip]);
        moveTooltip(e);
    }

    function moveTooltip(e) {
        if (tooltip.style.display === 'block') {
            let x = e.clientX + 15, y = e.clientY + 15;
            if (x + tooltip.offsetWidth > window.innerWidth) x = window.innerWidth - tooltip.offsetWidth - 10;
            if (y + tooltip.offsetHeight > window.innerHeight) y = window.innerHeight - tooltip.offsetHeight - 10;
            tooltip.style.left = x + 'px'; tooltip.style.top = y + 'px';
        }
    }

    function hideTooltip() { tooltip.style.display = 'none'; }

