    function renderPreview() {
        let theme = document.getElementById("theme-select").value;
        let customBg = getSelectedCustomBg();
        let themeWrapperStyle = '';
        if (theme === 'custom' && customBg) {
            themeWrapperStyle = ` style="background: #f4f7f6 url('${customBg}') center top / cover no-repeat fixed;"`;
        }
        let timerValue = document.getElementById("timer-input").value;
        let timerDisplay = timerValue > 0 ? `<div class="timer-box-preview">⏱ ${timerValue}:00</div>` : `<div class="timer-box-preview">⏱ 00:00</div>`;

        let signatureHTML = "";
        let teacherName = document.getElementById('teacher-name').value.trim();
        if (document.getElementById('toggle-signature').checked && teacherName !== '') {
            let verb = (document.getElementById('teacher-gender').value === 'male') ? 'подготовил' : 'подготовила';
            signatureHTML = `<div style="text-align: center; font-family: 'Caveat', cursive; font-size: 26px; color: #003399; margin-top: -10px; margin-bottom: 25px;">Вариант ${verb}: ${teacherName}</div>`;
        }

        let previewCode = currentInteractiveHTML.replace(/class="btn-settings btn-help" style="display:none;/g, 'class="btn-settings btn-help" style="display:inline-flex;');
        let outputSection = document.getElementById('output-section');
        outputSection.innerHTML = `<div class="theme-wrapper bg-${theme}"${themeWrapperStyle}><div class="preview-paper">${timerDisplay}<h1 style="color: #003399; text-align: center; border-bottom: 2px solid #ff8c00; padding-bottom: 15px; margin-top: 0;">${getCurrentVariantTitle()}</h1>${signatureHTML}${previewCode}</div></div>`;
        applySafeSvgPadding(outputSection);
        if (window.MathJax) {
            MathJax.typesetPromise([outputSection])
                .then(() => applySafeSvgPadding(outputSection))
                .catch((err) => console.log(err.message));
        } else {
            requestAnimationFrame(() => applySafeSvgPadding(outputSection));
        }
    }

    function applySafeSvgPadding(root = document) {
        if (!root || !root.querySelectorAll) return;

        root.querySelectorAll('svg').forEach(svg => {
            if (svg.dataset.safePaddingApplied === '1') {
                svg.style.overflow = 'visible';
                return;
            }

            const pad = { top: 24, right: 10, bottom: 10, left: 10 };
            let applied = false;
            const vb = svg.getAttribute('viewBox');

            if (vb) {
                const nums = vb.trim().split(/\s+|,/).map(Number).filter(n => !Number.isNaN(n));
                if (nums.length === 4) {
                    const [x, y, w, h] = nums;
                    svg.setAttribute('viewBox', `${x - pad.left} ${y - pad.top} ${w + pad.left + pad.right} ${h + pad.top + pad.bottom}`);
                    applied = true;
                }
            }

            if (!applied && svg.isConnected) {
                try {
                    const bbox = svg.getBBox();
                    if (bbox && isFinite(bbox.x) && isFinite(bbox.y) && bbox.width > 0 && bbox.height > 0) {
                        svg.setAttribute('viewBox', `${bbox.x - pad.left} ${bbox.y - pad.top} ${bbox.width + pad.left + pad.right} ${bbox.height + pad.top + pad.bottom}`);
                        applied = true;
                    }
                } catch (e) {}
            }

            svg.style.overflow = 'visible';
            if (applied) svg.dataset.safePaddingApplied = '1';
        });
    }

    function shuffleArray(array) {
        for (let i = array.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [array[i], array[j]] = [array[j], array[i]];
        }
        return array;
    }


    // Улучшает переносы только при показе текста; исходные task*.js не меняются.
    // 1) короткие записи вроде B₁C₁ = 8 и B₁K : KC₁ = 1 : 3 держатся вместе;
    // 2) короткое последнее обозначение/число не остаётся сиротой на отдельной строке;
    // 3) содержимое MathJax \(...\), \[...\] и $...$ не трогаем.
    function protectTaskTypography(html) {
        if (typeof html !== 'string' || !html) return html || '';

        // Пунктуация сразу после формулы должна переноситься вместе с формулой.
        // Иначе браузер/MathJax иногда оставляет точку или запятую в начале новой строки.
        const mathWithPunctuation = /(\\\([\s\S]*?\\\)|\$[^$]*\$)[ \t\u00A0]*([.!?,;:])/g;
        const protectedHtml = html.replace(
            mathWithPunctuation,
            '<span style="white-space:nowrap;">$1$2</span>'
        ).replace(/(\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]|\$[^$]*\$)/g,
            formula => formula.replace(/</g, '&lt;').replace(/>/g, '&gt;'));

        const template = document.createElement('template');
        template.innerHTML = protectedHtml;
        const walker = document.createTreeWalker(template.content, NodeFilter.SHOW_TEXT);
        const nodes = [];
        while (walker.nextNode()) nodes.push(walker.currentNode);

        const protectPlain = (source) => {
            let s = source;
            const NBSP = '\u00A0';

            // Короткие отношения/равенства: AB = 6, B₁C₁ = 8, 1 : 3.
            // Неразрывные пробелы переносят конструкцию целиком, а не оставляют "=" или цифру отдельно.
            s = s.replace(/([A-Za-zА-Яа-яЁё0-9₀-₉°]+)\s*([=≈≤≥<>])\s*([A-Za-zА-Яа-яЁё0-9₀-₉°√+−-]+(?:[.,]\d+)?)/gu,
                (_, left, op, right) => `${left}${NBSP}${op}${NBSP}${right}`);
            s = s.replace(/([A-Za-zА-Яа-яЁё0-9₀-₉°]+)\s*:\s*([A-Za-zА-Яа-яЁё0-9₀-₉°]+)/gu,
                (_, left, right) => `${left}${NBSP}:${NBSP}${right}`);

            // Не оставляем короткий хвост (8., D₁., M, 60° и т. п.) один на новой строке.
            s = s.replace(/\s+([^\s\u00A0]{1,4})([.!?,;:])(?=\s|$)/gu,
                (_, token, punct) => `${NBSP}${token}${punct}`);
            s = s.replace(/\s+([^\s\u00A0]{1,4})$/gu,
                (_, token) => `${NBSP}${token}`);

            return s;
        };

        // В одном текстовом узле могут одновременно быть обычный текст и TeX.
        // TeX-сегменты возвращаем без изменений, чтобы не мешать MathJax.
        const texPart = /(\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]|\$[^$]*\$)/g;
        nodes.forEach(node => {
            const value = node.nodeValue || '';
            const parts = value.split(texPart);
            node.nodeValue = parts.map(part => {
                if (/^(\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]|\$[^$]*\$)$/.test(part)) return part;
                return protectPlain(part);
            }).join('');
        });

        return template.innerHTML;
    }

    function generateVariant(options = {}) {
        const useRandomPicks = !!(options && options.useRandomPicks && window.randomVariantPicks);
        const useManualPlan = !useRandomPicks && !!(options && Array.isArray(options.manualPlan) && options.manualPlan.length);
        if (!useRandomPicks && !useManualPlan) {
            document.querySelectorAll('input[id^="count-"]').forEach(input => {
                if (!(parseInt(input.value, 10) > 0)) return;
                const { tid, kind } = getTaskCountTarget(input);
                const data = getPrototypeData(tid, kind);
                const hasSelection = data && Array.isArray(data.prototypes) && data.prototypes.some((p, idx) => {
                    const checkbox = document.getElementById(getPrototypeCheckboxId(tid, idx, kind));
                    return checkbox && checkbox.checked;
                });
                if (!hasSelection) {
                    const title = (data && data.title) || tid;
                    const label = kind === 'extra' ? `${window.database[tid]?.title || tid} — дополнительно` : title;
                    throw new Error(`В блоке «${label}» не выбраны темы. Откройте «Настроить» и отметьте нужные темы.`);
                }
            });
        }
        if (!useRandomPicks) {
            window.randomVariantMode = false;
            window.randomVariantPicks = null;
            window.randomVariantNumber = null;
            setRandomVariantButtonsVisible(false);
            if (!useManualPlan) window.manualVariantPlan = null;
        }
        const infoBoard = document.getElementById('info-board');
        infoBoard.style.display = 'none';
        infoBoard.innerHTML = '';
        currentInteractiveHTML = ""; currentPrintHTML = ""; currentAnswersHTML = ""; 

        const outputSection = document.getElementById('output-section');
        if (outputSection) {
            outputSection.style.display = 'none';
            outputSection.innerHTML = '';
        }

        const btnGroup = document.getElementById('btn-group');
        if (btnGroup) btnGroup.style.display = 'none';

        window.currentGeneratedTasks = []; window.selectedBlockTitles = [];
        window.mainCanvases = {}; 

        let taskCounter = 0, hasContent = false;
        let stickerPack = document.getElementById('sticker-select').value;
        let customStickers = getCustomStickerPack();
        let maxStickers = (stickerPack === 'custom') ? customStickers.length : ((stickerPack === 'ro') ? 10 : 5);
        if (stickerPack === 'custom' && maxStickers === 0) {
            infoBoard.innerHTML += `<div><b>Свой пакет стикеров:</b> пакет пустой, поэтому вариант будет создан без своих стикеров. Добавьте картинки через кнопку «Настроить стикеры».</div>`;
            infoBoard.style.display = 'block';
        }
        let lastStickerAddedAt = -1;
        let stickerCyclePool = [];
        let previousStickerId = -1;

        if (stickerPack !== lastStickerPack) {
            globalStickerPool = [];
            lastStickerPack = stickerPack;
            lastStickerId = -1;
        }

        function getNextSticker(maxS) {
            if (maxS <= 0) return -1;

            if (stickerCyclePool.length === 0) {
                stickerCyclePool = Array.from({ length: maxS }, (_, i) => i + 1);
                shuffleArray(stickerCyclePool);

                // pop() берёт последний элемент — именно его нельзя повторять.
                if (maxS > 1 && stickerCyclePool[stickerCyclePool.length - 1] === previousStickerId) {
                    const differentIndex = stickerCyclePool.findIndex(id => id !== previousStickerId);
                    if (differentIndex >= 0) {
                        const lastIndex = stickerCyclePool.length - 1;
                        [stickerCyclePool[differentIndex], stickerCyclePool[lastIndex]] =
                            [stickerCyclePool[lastIndex], stickerCyclePool[differentIndex]];
                    }
                }
            }

            let nextId = stickerCyclePool.pop();
            if (maxS > 1 && nextId === previousStickerId) {
                const differentIndex = stickerCyclePool.findIndex(id => id !== previousStickerId);
                if (differentIndex >= 0) {
                    [nextId, stickerCyclePool[differentIndex]] = [stickerCyclePool[differentIndex], nextId];
                }
            }

            previousStickerId = nextId;
            lastStickerId = nextId;
            return nextId;
        }

        let nextStickerTarget = 2 + Math.floor(Math.random() * 2);
        
        // Считываем состояние обеих галочек
        let includeExplanations = document.getElementById('toggle-explanations').checked;
        let instantCheck = document.getElementById('toggle-instant-check').checked;
        let showCorrectOnError = document.getElementById('toggle-show-correct').checked;
        let orderedTasks = document.getElementById('toggle-ordered-tasks') ? document.getElementById('toggle-ordered-tasks').checked : false;

        window.generatorSettings = {
            instantCheck: instantCheck,
            showCorrectOnError: showCorrectOnError,
            includeExplanations: includeExplanations,
            orderedTasks: orderedTasks
        };

        let sortedTaskIds = getUniqueTaskIds();
        const manualPlanBuilt = [];

        let generationBlocks = [];
        if (useRandomPicks) {
            // Случайный полный вариант: только main-база.
            // Для 1–13 это принципиально исключает файлы task*_extra.js.
            // В 14–20 расширенные аналоги уже входят в основные task14–task20.
            for (let n = 1; n <= 20; n++) {
                const tid = `task${n}`;
                const data = window.database[tid];
                const randomPick = window.randomVariantPicks[tid];
                if (data && randomPick) generationBlocks.push({ tid, kind: 'main', data, requiredCount: 1, randomPick });
            }
        } else if (useManualPlan) {
            // При точечной замене восстанавливаем весь уже собранный вариант
            // из сохранённого плана, чтобы изменилось только нажатое задание.
            const grouped = [];
            options.manualPlan.forEach((pick, planIndex) => {
                if (!pick || !pick.tid) return;
                const kind = pick.kind || 'main';
                let group = grouped[grouped.length - 1];
                if (!group || group.tid !== pick.tid || group.kind !== kind) {
                    const data = getPrototypeData(pick.tid, kind);
                    if (!data) return;
                    group = { tid: pick.tid, kind, data, requiredCount: 0, manualPicks: [] };
                    grouped.push(group);
                }
                group.manualPicks.push({ ...pick, planIndex });
                group.requiredCount++;
            });
            generationBlocks.push(...grouped);
        } else {
            sortedTaskIds.forEach(tid => {
                const mainCountInput = document.getElementById(`count-${tid}`);
                const mainCount = mainCountInput ? (parseInt(mainCountInput.value) || 0) : 0;
                if (mainCount > 0) {
                    generationBlocks.push({ tid, kind: 'main', data: window.database[tid], requiredCount: mainCount });
                }

                const extraData = getExtraTaskData(tid);
                const extraCountInput = document.getElementById(`count-extra-${tid}`);
                const extraCount = extraCountInput ? (parseInt(extraCountInput.value) || 0) : 0;
                if (extraData && extraCount > 0) {
                    generationBlocks.push({ tid, kind: 'extra', data: extraData, requiredCount: extraCount });
                }
            });
        }

        for (let block of generationBlocks) {
            let tid = block.tid;
            let data = block.data;
            let requiredCount = block.requiredCount;
            let kind = block.kind || 'main';
            if (!data || !Array.isArray(data.prototypes)) continue;

            const randomPick = useRandomPicks ? block.randomPick : null;
            const manualPicks = Array.isArray(block.manualPicks) ? block.manualPicks : null;
            const visibleBlockTitle = (kind === 'extra') ? 'Дополнительно' : data.title;
            const isSecondPartBlock = Number(data.part || 1) >= 2;
            let finalTasks = [];

            if (manualPicks) {
                manualPicks.forEach(pick => {
                    const proto = data.prototypes[pick.protoIndex];
                    if (!proto || !Array.isArray(proto.tasks) || !proto.tasks.length) return;
                    let task = proto.tasks[pick.taskIndex];
                    const expectedKey = String(pick.taskKey ?? '');
                    if (!task || String(task && (task.id ?? task.text ?? pick.taskIndex)) !== expectedKey) {
                        const foundIndex = proto.tasks.findIndex((candidate, idx) => String(candidate && (candidate.id ?? candidate.text ?? idx)) === expectedKey);
                        if (foundIndex >= 0) {
                            task = proto.tasks[foundIndex];
                            pick.taskIndex = foundIndex;
                        }
                    }
                    if (!task) return;
                    finalTasks.push({
                        ...task,
                        svg: task.svg_code || proto.svg_code || "",
                        theory: proto,
                        prototype: proto,
                        protoIndex: pick.protoIndex,
                        sourceTaskIndex: pick.taskIndex,
                        sourcePlanIndex: pick.planIndex,
                        allProtoTasks: [...proto.tasks]
                    });
                });
            } else {
                let selectedProtos = randomPick
                    ? [data.prototypes[randomPick.protoIndex]].filter(Boolean)
                    : data.prototypes.filter((p, idx) => {
                        const cb = document.getElementById(getPrototypeCheckboxId(tid, idx, kind));
                        return cb && cb.checked;
                    });
                if (selectedProtos.length === 0) continue;

                let activePools = selectedProtos.map((p, selectedIndex) => {
                    const originalProtoIndex = randomPick ? randomPick.protoIndex : data.prototypes.indexOf(p);
                    const chosenTask = randomPick && p.tasks ? p.tasks[randomPick.taskIndex] : null;
                    const poolTasks = chosenTask ? [chosenTask] : shuffleArray([...p.tasks]);
                    return {
                        tasks: poolTasks,
                        allTasks: [...p.tasks],
                        protoSvg: p.svg_code || "",
                        theory: p,
                        prototype: p,
                        protoIndex: originalProtoIndex >= 0 ? originalProtoIndex : selectedIndex
                    };
                });

                const availableCount = activePools.reduce((sum, pool) => sum + pool.tasks.length, 0);
                const requestedCount = requiredCount;
                const actualCount = requiredCount;

                if (availableCount === 0) {
                    infoBoard.innerHTML += `<div><b>${data.title}:</b> в выбранных прототипах нет доступных задач.</div>`;
                    infoBoard.style.display = 'block';
                    continue;
                }

                if (requestedCount > availableCount) {
                    infoBoard.innerHTML += `<div><b>${data.title}:</b> запрошено ${requestedCount}, уникальных задач в выбранных прототипах ${availableCount}. После первого круга задачи будут повторяться по новому кругу.</div>`;
                    infoBoard.style.display = 'block';
                }

                function buildPrototypeRound() {
                    let pools = activePools.map(pool => ({
                        protoSvg: pool.protoSvg || "",
                        theory: pool.theory,
                        prototype: pool.prototype || pool.theory,
                        protoIndex: pool.protoIndex,
                        allTasks: [...(pool.allTasks || pool.tasks || [])],
                        tasks: shuffleArray([...pool.tasks])
                    })).filter(pool => pool.tasks.length > 0);

                    if (!orderedTasks) pools = shuffleArray(pools);

                    const maxTasksInProto = Math.max(...pools.map(pool => pool.tasks.length));
                    let roundTasks = [];
                    for (let layerIndex = 0; layerIndex < maxTasksInProto; layerIndex++) {
                        let layerPools = pools.filter(pool => pool.tasks[layerIndex]);
                        if (!orderedTasks) layerPools = shuffleArray(layerPools);
                        layerPools.forEach(pool => {
                            const task = pool.tasks[layerIndex];
                            const allTasks = pool.allTasks || [];
                            const sourceTaskIndex = allTasks.indexOf(task);
                            roundTasks.push({
                                ...task,
                                svg: task.svg_code || pool.protoSvg || "",
                                theory: pool.theory,
                                prototype: pool.prototype || pool.theory,
                                protoIndex: pool.protoIndex,
                                sourceTaskIndex: sourceTaskIndex >= 0 ? sourceTaskIndex : 0,
                                allProtoTasks: [...allTasks]
                            });
                        });
                    }
                    return roundTasks;
                }

                let oneFullRound = buildPrototypeRound();
                if (oneFullRound.length === 0) continue;
                while (finalTasks.length < actualCount) {
                    const cycleTasks = finalTasks.length === 0 ? [...oneFullRound] : buildPrototypeRound();
                    const needNow = actualCount - finalTasks.length;
                    finalTasks.push(...cycleTasks.slice(0, needNow));
                }
            }

            if (finalTasks.length === 0) continue;
            window.selectedBlockTitles.push(visibleBlockTitle);
            if (isSecondPartBlock) {
                const selectedIdsByProto = {};
                finalTasks.forEach(t => {
                    const key = String(t.protoIndex ?? '');
                    selectedIdsByProto[key] = selectedIdsByProto[key] || new Set();
                    selectedIdsByProto[key].add(String(t.id ?? t.text ?? ''));
                });
                finalTasks.forEach(t => {
                    const key = String(t.protoIndex ?? '');
                    const selectedIds = selectedIdsByProto[key] || new Set();
                    const prototypeSvg = (t.prototype && t.prototype.svg_code) ? t.prototype.svg_code : "";
                    t.analogs = (t.allProtoTasks || [])
                        .filter(a => !selectedIds.has(String(a.id ?? a.text ?? '')))
                        .map(a => ({ ...a, svg: a.svg || a.svg_code || prototypeSvg || "" }));
                });
            }
            hasContent = true;

            if (useRandomPicks && parseInt(String(tid).replace(/\D/g, ''), 10) === 14) {
                const secondPartHeading = `<div style="margin:34px 0 12px;padding:11px 14px;border-bottom:2px solid #ff8c00;color:#ff8c00;font-size:21px;font-weight:800;text-align:center;">Задания с развёрнутым ответом</div>`;
                currentInteractiveHTML += secondPartHeading;
                currentPrintHTML += secondPartHeading;
                currentAnswersHTML += `<h2 style="color:#ff8c00;text-align:center;">Задания с развёрнутым ответом</h2>`;
            }

            let blockTitle = `<h3 style="background: #e3f2fd; padding: 10px 15px; border-left: 4px solid #003399; margin-top: 30px; border-radius: 0 6px 6px 0; color: #003399;">${visibleBlockTitle}</h3>`;
            currentInteractiveHTML += blockTitle + `<div style="font-size: 16px;">`;
            currentPrintHTML += blockTitle + `<div style="font-size: 16px;">`;
            currentAnswersHTML += `<h3>${visibleBlockTitle}</h3><div>`;

            finalTasks.forEach(item => {
                taskCounter++;
                let mainSvg = item.svg || item.svg_code || "";
                if (mainSvg) { let tmp = document.createElement('div'); tmp.innerHTML = mainSvg; window.autoFixSVGArrows(tmp); applySafeSvgPadding(tmp); mainSvg = tmp.innerHTML; }
                
                let theorySvgCode = item.theory && item.theory.svg_code ? item.theory.svg_code : "";
                if (theorySvgCode) {
                    let tmp = document.createElement('div'); tmp.innerHTML = theorySvgCode; window.autoFixSVGArrows(tmp); applySafeSvgPadding(tmp); theorySvgCode = tmp.innerHTML;
                }
                
                let theoryHtml = "";
                if (!isSecondPartBlock && item.theory) {
                    theoryHtml = `
                        <div id="theory-solution-${taskCounter}">
                            <h3>Разбор аналогичного задания</h3>
                            <div style='background:#f9f9f9;padding:15px;border-left:4px solid #ff8c00;margin-bottom:15px;border-radius:6px;'>
                                <p style='margin-top:0;'><b>Задача:</b></p>
                                <div style='min-height: 60px;'>${theorySvgCode ? '<div style="float:left; margin-right: 20px; margin-bottom: 10px; max-width: 300px;">' + theorySvgCode + '</div>' : ''}${item.theory.theory_task}</div><div style='clear:both;'></div>
                                <p style='margin-top: 20px;'><b>Решение:</b></p>
                                <div>${item.theory.theory_sol}</div>
                                <div style="display:flex;justify-content:flex-end;margin-top:18px;padding-top:12px;border-top:1px solid #e6e6e6;">
                                    <button type="button" onclick="document.getElementById('theory-solution-${taskCounter}').style.display='none'" style="background:#fff3e0;color:#e65100;border:1px solid #ffb74d;border-radius:7px;padding:8px 17px;font-weight:700;cursor:pointer;">Скрыть</button>
                                </div>
                            </div>
                        </div>
                        <h4 style='color: #ff8c00;'>Задачи для отработки:</h4>
                        <ul style='padding-left:20px;'>
                    `;
                    if(item.theory.tasks) {
                        item.theory.tasks.forEach((t, practiceIndex) => {
                            // Если у конкретной задачи нет собственного svg_code, берём чертёж прототипа.
                            // Так после скрытия верхнего разбора чертёж не исчезает у задач для отработки.
                            let tSvgCode = t.svg_code || item.theory.svg_code || "";
                            if (tSvgCode) { let tmp = document.createElement('div'); tmp.innerHTML = tSvgCode; window.autoFixSVGArrows(tmp); applySafeSvgPadding(tmp); tSvgCode = tmp.innerHTML; }
                            let tSvg = tSvgCode ? `<div class="generated-task-diagram" style="margin:10px 0;max-width:320px;padding:14px 8px 6px;box-sizing:border-box;overflow:visible;">${tSvgCode}</div>` : '';
                            const practiceDraftId = `practice-${taskCounter}-${practiceIndex + 1}`;
                            const practiceDiagramHTML = buildDraftDiagramCardHTML(practiceDraftId, tSvgCode);
                            const practiceScratchpad = buildInlineScratchpadHTML(practiceDraftId, false, practiceDiagramHTML);
                            theoryHtml += `<li style='margin-bottom:18px;'><div style="display:flex;align-items:flex-start;gap:8px;"><div style="flex:1;min-width:0;">${protectTaskTypography(t.text)}${tSvg}</div><button type="button" onclick="window.toggleCanvas('${practiceDraftId}')" title="Открыть черновик" style="flex:0 0 auto;background:#fff3e0;color:#e65100;border:1px solid #ffcc80;border-radius:6px;font-size:18px;padding:5px 9px;cursor:pointer;">✏️</button></div><div style="margin-top:7px;"><span style='color:#003399;cursor:pointer;border-bottom:1px dashed #003399;' onclick='this.innerText="Ответ: ${t.answer}"; this.style.border="none"; this.style.fontWeight="bold";'>Показать ответ</span></div>${practiceScratchpad}</li>`;
                        });
                    }
                    theoryHtml += `</ul>`;
                }

                let analogsHtml = "";
                if (isSecondPartBlock) {
                    const analogList = Array.isArray(item.analogs) ? item.analogs : [];
                    analogsHtml = `<h3 style="margin-top:0;color:#003399;">Аналоги</h3>`;
                    if (!analogList.length) {
                        analogsHtml += `<div style="padding:14px;background:#f5f5f5;border-radius:8px;">Все похожие задания этого типа уже вошли в текущий вариант.</div>`;
                    } else {
                        analogsHtml += `<ol style="padding-left:24px;">`;
                        analogList.forEach((a, analogIndex) => {
                            const analogDraftId = `analog-${taskCounter}-${analogIndex + 1}`;
                            let analogSvgCode = a.svg || a.svg_code || (item.prototype && item.prototype.svg_code) || "";
                            if (analogSvgCode) {
                                let tmp = document.createElement('div');
                                tmp.innerHTML = analogSvgCode;
                                window.autoFixSVGArrows(tmp);
                                applySafeSvgPadding(tmp);
                                analogSvgCode = tmp.innerHTML;
                            }
                            const analogDiagram = analogSvgCode ? `<div class="generated-task-diagram" style="margin:10px 0;max-width:340px;padding:14px 8px 6px;box-sizing:border-box;overflow:visible;">${analogSvgCode}</div>` : "";
                            const analogDiagramHTML = buildDraftDiagramCardHTML(analogDraftId, analogSvgCode);
                            const analogScratchpad = buildInlineScratchpadHTML(analogDraftId, true, analogDiagramHTML);
                            analogsHtml += `<li style="margin-bottom:20px;"><div style="display:flex;align-items:flex-start;gap:8px;"><div style="flex:1;min-width:0;">${protectTaskTypography(a.text)}${analogDiagram}</div><button type="button" onclick="window.toggleCanvas('${analogDraftId}')" title="Открыть черновик" style="flex:0 0 auto;background:#fff3e0;color:#e65100;border:1px solid #ffcc80;border-radius:6px;font-size:18px;padding:5px 9px;cursor:pointer;">✏️</button></div>${analogScratchpad}`;
                            if (showCorrectOnError) analogsHtml += `<div style="margin-top:8px;padding:9px 12px;background:#eef6ff;border-left:3px solid #003399;border-radius:5px;"><b>Ответ:</b> ${a.answer}</div>`;
                            analogsHtml += `</li>`;
                        });
                        analogsHtml += `</ol>`;
                    }
                }

                const sourceTaskIndex = Number.isInteger(item.sourceTaskIndex)
                    ? item.sourceTaskIndex
                    : (item.prototype && Array.isArray(item.prototype.tasks) ? item.prototype.tasks.indexOf(item) : 0);
                const taskKey = String(item && (item.id ?? item.text ?? sourceTaskIndex));
                const manualPlanIndex = useRandomPicks ? -1 : manualPlanBuilt.length;
                if (!useRandomPicks) {
                    manualPlanBuilt.push({
                        tid,
                        kind,
                        protoIndex: item.protoIndex,
                        taskIndex: sourceTaskIndex >= 0 ? sourceTaskIndex : 0,
                        taskKey
                    });
                }

                window.currentGeneratedTasks.push({
                    text: item.text,
                    svg: mainSvg,
                    answer: String(item.answer),
                    theory: theoryHtml,
                    analogsHtml: analogsHtml,
                    analogs: isSecondPartBlock ? (item.analogs || []).map(a => ({ id: a.id, text: a.text, answer: a.answer, svg: a.svg || a.svg_code || "" })) : [],
                    part: isSecondPartBlock ? 2 : 1,
                    isSecondPart: isSecondPartBlock,
                    prototypeCode: item.prototype && item.prototype.code ? item.prototype.code : "",
                    prototypeTitle: item.prototype && item.prototype.desc ? `${item.prototype.desc} (${Array.isArray(item.prototype.tasks) ? item.prototype.tasks.length : 0})` : "",
                    showCorrectOnError: showCorrectOnError,
                    instantCheck: instantCheck,
                    taskId: item.id ?? null,
                    taskTid: tid,
                    taskKind: kind,
                    protoIndex: item.protoIndex,
                    sourceTaskIndex: sourceTaskIndex >= 0 ? sourceTaskIndex : 0,
                    taskKey,
                    manualPlanIndex,
                    randomVariant: useRandomPicks
                });
                
                let stickerHTMLInteractive = "";
                let stickerHTMLPrint = "";
                let pr = 0;

                if (stickerPack !== 'none' && maxStickers > 0 && taskCounter === nextStickerTarget) {
                    lastStickerAddedAt = taskCounter;
                    let sIdx = getNextSticker(maxStickers), rot = Math.floor(Math.random() * 31) - 15;
                    let mw = 112, mh = 96;
                    let stickerSrc = "";
                    let quote = "";

                    if (stickerPack === 'custom') {
                        stickerSrc = customStickers[sIdx - 1] || "";
                        mw = 120;
                        mh = 105;
                    } else {
                        if (stickerPack === 'sci') {
                            if ([1,4].includes(sIdx)) { mw *= 1.8; mh *= 1.8; }
                            else if (sIdx === 3) { mw *= 1.35; mh *= 1.35; }
                            else if (sIdx === 5) { mw *= 1.5; mh *= 1.5; }
                        } else if (stickerPack === 'ro') { mw *= 1.3; mh *= 1.3; }

                        stickerSrc = window.getEmbeddedAssetUrl(stickerPack + '_' + sIdx + '.png');
                        quote = (stickerPack === 'sci' && sciQuotes[sIdx]) ? `<div style="font-family:'Caveat', cursive; font-size:16px; color:#003399; margin-top:5px; transform:rotate(${rot/3}deg); text-align:center; line-height:1.1; width: 100%; word-wrap: break-word;">${sciQuotes[sIdx]}</div>` : "";
                    }

                    if (stickerSrc) {
                        // Поворот увеличивает фактические габариты изображения.
                        const stickerAngle = Math.abs(rot) * Math.PI / 180;
                        const stickerBoxW = Math.ceil(mw * Math.cos(stickerAngle) + mh * Math.sin(stickerAngle)) + 24;
                        const stickerBoxH = Math.ceil(mh * Math.cos(stickerAngle) + mw * Math.sin(stickerAngle)) + 24;

                        stickerHTMLInteractive = `<div class="generated-sticker" style="flex:0 0 ${stickerBoxW}px; margin-left:12px; width:${stickerBoxW}px; min-height:${stickerBoxH}px; padding:16px 12px; box-sizing:border-box; display:flex; flex-direction:column; align-items:center; justify-content:center; overflow:visible; page-break-inside:avoid;"><img src="${stickerSrc}" style="display:block;max-width:${mw}px;max-height:${mh}px;transform:rotate(${rot}deg);transform-origin:center center;filter:drop-shadow(2px 4px 6px rgba(0,0,0,0.15));pointer-events:none;object-fit:contain;overflow:visible;">${quote}</div>`;

                        stickerHTMLPrint = `<div class="sticker-print generated-sticker" style="flex:0 0 ${stickerBoxW}px; width:${stickerBoxW}px; min-height:${stickerBoxH}px; padding:14px 10px; box-sizing:border-box; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; overflow:visible; page-break-inside:avoid; break-inside:avoid; align-self:center; margin-left:12px;"><img src="${stickerSrc}" style="display:block;max-width:${mw}px;max-height:${mh}px;transform:rotate(${rot}deg);transform-origin:center center;filter:drop-shadow(2px 4px 6px rgba(0,0,0,0.15));pointer-events:none;object-fit:contain;overflow:visible;">${quote}</div>`;

                        pr = stickerBoxW;
                    }

                    nextStickerTarget += 3 + Math.floor(Math.random() * 2);
                }

                // Первая часть: ввод ответа и разбор. Вторая часть: аналоги и самопроверка по ответу.
                let instantBtn = (!isSecondPartBlock && instantCheck) ? `<button class="btn-instant" onclick="checkSingle(this, ${taskCounter}, '${item.answer}')" style="background: #e8f5e9; border: 1px solid #4CAF50; border-radius: 6px; font-size: 18px; cursor: pointer; padding: 8px 12px; outline: none; transition: 0.2s;" title="Проверить">✅</button>` : "";
                let drawBtn = `<button class="btn-settings" style="background: #fff3e0; color: #e65100; border: 1px solid #ffcc80; font-size: 18px; padding: 8px 12px;" onclick="window.toggleCanvas('${taskCounter}')" title="Открыть черновик">✏️</button>`;
                let helpBtn = (!isSecondPartBlock && includeExplanations && item.theory) ? `<button id="btn-help-${taskCounter}" class="btn-settings btn-help" style="display:none; background: #e3f2fd; color: #003399; border: 1px solid #003399; font-weight: bold; padding: 10px 15px;" onclick="window.openTheoryModalLocal('theory-data-${taskCounter}')">РАЗБОР</button><div id="theory-data-${taskCounter}" style="display:none;">${encodeURIComponent(theoryHtml)}</div>` : "";
                let secondPartButtons = isSecondPartBlock ? `
                    ${instantCheck ? `<button class="btn-settings second-answer-btn" id="second-answer-btn-${taskCounter}" style="background:#e8f5e9;color:#1b5e20;border:1px solid #4CAF50;font-weight:bold;padding:9px 13px;" onclick="window.showSecondPartAnswer('${taskCounter}')">ПОКАЗАТЬ ОТВЕТ</button>` : ""}
                    <button class="btn-settings" style="background:#e3f2fd;color:#003399;border:1px solid #003399;font-weight:bold;padding:9px 13px;" onclick="window.openTheoryModalLocal('analogs-data-${taskCounter}')">АНАЛОГИ</button>
                    <div id="analogs-data-${taskCounter}" style="display:none;">${encodeURIComponent(analogsHtml)}</div>
                    <div id="second-answer-data-${taskCounter}" style="display:none;">${encodeURIComponent(String(item.answer))}</div>
                ` : "";

                // Любой реальный чертёж задачи переносим и в её черновик — без жёсткого списка номеров.
                let draftDiagramSource = mainSvg || "";
                if (!draftDiagramSource && item.text) {
                    let tmpDiagram = document.createElement('div');
                    tmpDiagram.innerHTML = item.text;
                    window.autoFixSVGArrows(tmpDiagram);
                    let foundDiagram = tmpDiagram.querySelector('svg, img, picture, canvas');
                    if (foundDiagram) draftDiagramSource = foundDiagram.outerHTML;
                }
                const draftDiagramHTML = buildDraftDiagramCardHTML(String(taskCounter), draftDiagramSource);
                let scratchpadHTML = buildInlineScratchpadHTML(String(taskCounter), isSecondPartBlock, draftDiagramHTML);

                const displayTaskText = protectTaskTypography(item.text);
                const taskActionArea = isSecondPartBlock
                    ? `<div style="margin-top:15px;display:flex;align-items:center;flex-wrap:wrap;gap:10px;clear:both;">${drawBtn}${secondPartButtons}<div class="second-part-final-answer" id="second-final-answer-${taskCounter}" style="display:none;width:100%;margin-top:8px;padding:12px 14px;background:#eef6ff;border-left:4px solid #003399;border-radius:6px;"><b>Ответ:</b> ${item.answer}</div></div>`
                    : `<div style="margin-top:15px; display:flex; align-items:center; flex-wrap:wrap; gap:10px; clear:both;"><input type="text" class="ans-box" id="ans-interactive-${taskCounter}" placeholder="Ответ..." data-ans="${item.answer}" style="padding:10px 15px; border:2px solid #ccc; border-radius:6px; font-size:16px; font-weight:bold; width:150px; outline:none; transition:0.3s;">${instantBtn}${drawBtn}${helpBtn}<span class="answer-feedback" id="feedback-${taskCounter}" style="font-weight:bold; font-size:15px; display:none;"></span></div>`;
                const randomTaskNumber = parseInt(String(tid).replace(/\D/g, ''), 10);
                const replaceButtons = buildVariantReplacementButtons(tid,kind,item,manualPlanIndex,useRandomPicks);
                currentInteractiveHTML += `<div class="generated-task-block ${isSecondPartBlock ? 'second-part-task' : 'first-part-task'}" data-part="${isSecondPartBlock ? 2 : 1}" data-random-task-number="${randomTaskNumber}" data-manual-plan-index="${manualPlanIndex}" style="margin-bottom:30px; clear:both; overflow:visible; position:relative; border-bottom:1px dashed #ddd; padding:8px 0 20px;">${replaceButtons}<div style="display:flex; align-items:flex-start; justify-content:space-between; gap:10px; overflow:visible;"><div style="display:flex; align-items:flex-start; gap:15px; flex-grow:1; min-width:0; overflow:visible;"><div style="flex-shrink:0; font-weight:bold; font-size:1.1em; padding-top:2px;">${taskCounter}.</div>${mainSvg ? `<div class="generated-task-diagram" style="flex-shrink:0; min-width:150px; max-width:350px; padding:22px 8px 6px; box-sizing:border-box; overflow:visible;">${mainSvg}</div>` : ""}<div style="flex-grow:1; min-width:0;"><div class="task-copy">${displayTaskText}</div>${taskActionArea}</div></div><div style="display:flex;align-items:flex-start;gap:8px;">${stickerHTMLInteractive}</div></div>${scratchpadHTML}</div>`;
                
                // Only the printable copy of Task 9 uses a contrast-boosted raster;
                // the interactive diagram and mathematical task data stay untouched.
                const printableDiagram = (randomTaskNumber === 9 && mainSvg)
                    ? mainSvg.replace(/img8\/(img\d+\.png)/g, 'img8/print/$1')
                    : mainSvg;
                currentPrintHTML += `<div class="task-print-block"><div class="task-print-flex"><div class="task-print-num">${taskCounter}</div>${printableDiagram ? `<div class="task-print-img">${printableDiagram}</div>` : ""}<div class="task-print-text"><div class="task-copy">${displayTaskText}</div>${isSecondPartBlock ? `<div class="task-print-answer" style="margin-top:10px;color:#777;">Решение выполняется с полным обоснованием.</div>` : `<div class="task-print-answer">Ответ: ______________________________</div>`}</div>${stickerHTMLPrint}</div></div>`;
                
                currentAnswersHTML += isSecondPartBlock
                    ? `<div style="margin-bottom:18px;font-size:18px;"><b>${taskCounter}.</b><div style="margin-top:6px;color:#d32f2f;">${item.answer}</div></div>`
                    : `<div style="margin-bottom: 10px; font-size: 18px;"><b>${taskCounter}.</b> Ответ: <strong style="color: #d32f2f;">${item.answer}</strong></div>`;
            });
            currentInteractiveHTML += `</div>`; currentPrintHTML += `</div>`; currentAnswersHTML += `</div>`;
        }

        if (hasContent) {
            if (!useRandomPicks) window.manualVariantPlan = manualPlanBuilt.map(item => ({ ...item }));
            // При сборке пачки 1–40 не отрисовываем интерактивный лист 40 раз.
            // Готовые HTML и задачи сохраняются, а предпросмотр строится один раз
            // для первого варианта после завершения полной пачки.
            if (!options.silent) {
                document.getElementById('output-section').style.display = 'block';
                document.getElementById('btn-group').style.display = 'flex';
                setRandomVariantButtonsVisible(useRandomPicks);
                renderPreview();
            }
        }
    }

    window.CANVAS_LOGIC_SCRIPT = `
        window.mainCanvases = {};

        window.openDraftVisualZoom = window.openDraftVisualZoom || function(sourceEl) {
            if (!sourceEl) return;
            const visual = sourceEl.matches && sourceEl.matches('svg,img,picture,canvas') ? sourceEl : sourceEl.querySelector('svg,img,picture,canvas');
            if (!visual) return;

            let overlay = document.getElementById('draftVisualZoomOverlay');
            if (!overlay) {
                overlay = document.createElement('div');
                overlay.id = 'draftVisualZoomOverlay';
                overlay.style.cssText = 'position:fixed;inset:0;z-index:1000000;background:rgba(0,0,0,.82);display:none;align-items:center;justify-content:center;padding:18px;box-sizing:border-box;';
                overlay.innerHTML = '<div data-z="dialog" style="position:relative;width:min(1180px,97vw);height:min(860px,94vh);background:#fff;border-radius:18px;box-shadow:0 24px 80px rgba(0,0,0,.55);overflow:hidden;display:flex;flex-direction:column;"><div style="display:flex;align-items:center;justify-content:center;gap:8px;padding:9px;background:#eef6ff;border-bottom:1px solid #c9dff2;flex:0 0 auto;"><button type="button" data-z="out" title="Уменьшить" style="font-size:20px;border:1px solid #90caf9;background:#fff;border-radius:8px;min-width:38px;height:36px;cursor:pointer;">−</button><button type="button" data-z="reset" title="Показать целиком" style="font-size:16px;border:1px solid #90caf9;background:#fff;border-radius:8px;height:36px;cursor:pointer;">100%</button><button type="button" data-z="in" title="Увеличить" style="font-size:20px;border:1px solid #90caf9;background:#fff;border-radius:8px;min-width:38px;height:36px;cursor:pointer;">+</button><button type="button" data-z="close" title="Закрыть" style="margin-left:auto;font-size:24px;border:1px solid #ffcc80;background:#fff3e0;color:#e65100;border-radius:8px;width:38px;height:36px;cursor:pointer;">×</button></div><div data-z="viewport" style="flex:1;min-height:0;overflow:auto;padding:18px;box-sizing:border-box;background:#fff;"><div data-z="stage" style="min-width:100%;min-height:100%;display:flex;align-items:center;justify-content:center;box-sizing:border-box;"><div data-z="content" style="flex:0 0 auto;line-height:0;"></div></div></div></div>';
                document.body.appendChild(overlay);

                const close = () => {
                    overlay.style.display = 'none';
                    document.body.style.overflow = overlay.dataset.oldOverflow || '';
                };
                overlay.addEventListener('click', e => {
                    if (e.target === overlay || e.target.closest('[data-z="close"]')) close();
                });
                document.addEventListener('keydown', e => {
                    if (e.key === 'Escape' && overlay.style.display !== 'none') close();
                });

                const changeScale = delta => {
                    if (!overlay._apply) return;
                    overlay._scale = Math.max(.5, Math.min(4, (overlay._scale || 1) + delta));
                    overlay._apply();
                };
                overlay.querySelector('[data-z="in"]').addEventListener('click', () => changeScale(.25));
                overlay.querySelector('[data-z="out"]').addEventListener('click', () => changeScale(-.25));
                overlay.querySelector('[data-z="reset"]').addEventListener('click', () => {
                    if (!overlay._apply) return;
                    overlay._scale = 1;
                    overlay._apply();
                });
                overlay.querySelector('[data-z="viewport"]').addEventListener('wheel', e => {
                    if (!e.ctrlKey) return;
                    e.preventDefault();
                    changeScale(e.deltaY < 0 ? .15 : -.15);
                }, {passive:false});
                window.addEventListener('resize', () => {
                    if (overlay.style.display !== 'none' && overlay._refit) overlay._refit();
                });
            }

            const content = overlay.querySelector('[data-z="content"]');
            const stage = overlay.querySelector('[data-z="stage"]');
            const viewport = overlay.querySelector('[data-z="viewport"]');
            content.innerHTML = '';

            let clone;
            if (visual.tagName && visual.tagName.toLowerCase() === 'canvas') {
                clone = document.createElement('img');
                try {
                    clone.src = visual.toDataURL('image/png');
                } catch(e) {
                    return;
                }
            } else {
                clone = visual.cloneNode(true);
            }

            clone.removeAttribute && clone.removeAttribute('id');
            clone.style.cssText = 'display:block!important;max-width:none!important;max-height:none!important;width:100%!important;height:100%!important;min-width:0!important;min-height:0!important;object-fit:contain!important;margin:0!important;';

            if (clone.tagName && clone.tagName.toLowerCase() === 'picture') {
                const pictureImg = clone.querySelector('img');
                if (pictureImg) {
                    pictureImg.style.cssText = 'display:block!important;max-width:none!important;max-height:none!important;width:100%!important;height:100%!important;min-width:0!important;min-height:0!important;object-fit:contain!important;margin:0!important;';
                }
            }

            content.appendChild(clone);

            const sourceRect = visual.getBoundingClientRect();
            let ratio = sourceRect.width > 0 && sourceRect.height > 0 ? sourceRect.width / sourceRect.height : 1;
            const tag = visual.tagName ? visual.tagName.toLowerCase() : '';

            if (tag === 'img' && visual.naturalWidth > 0 && visual.naturalHeight > 0) {
                ratio = visual.naturalWidth / visual.naturalHeight;
            } else if (tag === 'canvas' && visual.width > 0 && visual.height > 0) {
                ratio = visual.width / visual.height;
            } else if (tag === 'svg' && visual.viewBox && visual.viewBox.baseVal && visual.viewBox.baseVal.width > 0 && visual.viewBox.baseVal.height > 0) {
                ratio = visual.viewBox.baseVal.width / visual.viewBox.baseVal.height;
            } else if (tag === 'picture') {
                const sourceImg = visual.querySelector('img');
                if (sourceImg && sourceImg.naturalWidth > 0 && sourceImg.naturalHeight > 0) {
                    ratio = sourceImg.naturalWidth / sourceImg.naturalHeight;
                }
            }

            if (!isFinite(ratio) || ratio <= 0) ratio = 1;
            overlay._ratio = ratio;
            overlay._scale = 1;

            overlay._apply = () => {
                const scale = overlay._scale || 1;
                const width = Math.max(1, (overlay._baseWidth || 1) * scale);
                const height = Math.max(1, (overlay._baseHeight || 1) * scale);

                content.style.width = width + 'px';
                content.style.height = height + 'px';

                const viewportWidth = Math.max(0, viewport.clientWidth - 36);
                const viewportHeight = Math.max(0, viewport.clientHeight - 36);
                stage.style.justifyContent = width <= viewportWidth + 1 ? 'center' : 'flex-start';
                stage.style.alignItems = height <= viewportHeight + 1 ? 'center' : 'flex-start';

                overlay.querySelector('[data-z="reset"]').textContent = Math.round(scale * 100) + '%';
            };

            overlay._refit = () => {
                const styles = window.getComputedStyle(viewport);
                const padX = (parseFloat(styles.paddingLeft) || 0) + (parseFloat(styles.paddingRight) || 0);
                const padY = (parseFloat(styles.paddingTop) || 0) + (parseFloat(styles.paddingBottom) || 0);
                const availableWidth = Math.max(120, viewport.clientWidth - padX);
                const availableHeight = Math.max(120, viewport.clientHeight - padY);
                const ratioNow = overlay._ratio || 1;

                let baseWidth = availableWidth;
                let baseHeight = baseWidth / ratioNow;
                if (baseHeight > availableHeight) {
                    baseHeight = availableHeight;
                    baseWidth = baseHeight * ratioNow;
                }

                overlay._baseWidth = Math.max(1, Math.floor(baseWidth));
                overlay._baseHeight = Math.max(1, Math.floor(baseHeight));
                overlay._apply();
            };

            overlay.dataset.oldOverflow = document.body.style.overflow || '';
            document.body.style.overflow = 'hidden';
            overlay.style.display = 'flex';

            requestAnimationFrame(() => overlay._refit());
        };
        window.openTheoryModalLocal = function(dataId) {
            let el = document.getElementById(dataId);
            if(el) {
                document.getElementById('modal-content-box').innerHTML = decodeURIComponent(el.textContent);
                document.getElementById('modal-overlay').style.display = 'flex';
                if (window.MathJax && typeof MathJax.typesetPromise === 'function') MathJax.typesetPromise([document.getElementById('modal-overlay')]).catch(console.error);
            }
        };
        window.showSecondPartAnswer = function(id) {
            const data = document.getElementById('second-answer-data-' + id);
            const target = document.getElementById('second-final-answer-' + id);
            const btn = document.getElementById('second-answer-btn-' + id);
            if (!data || !target) return;
            target.innerHTML = '<b>Ответ:</b> ' + decodeURIComponent(data.textContent || '');
            target.style.display = 'block';
            if (btn) btn.style.display = 'none';
            if (window.MathJax && MathJax.typesetPromise) MathJax.typesetPromise([target]).catch(()=>{});
        };
        window.toggleCanvas = function(id) {
            let w = document.getElementById('draw-wrapper-' + id);
            if (w.style.display === 'none' || w.style.display === '') { w.style.display = 'block'; setTimeout(() => window.initMainCanvas(id), 50); } else { w.style.display = 'none'; }
        };
        window.initMainCanvas = function(id) {
            let canvas = document.getElementById('canvas-' + id); 
            if(!canvas) return;
            if (window.mainCanvases[id] && window.mainCanvases[id].canvas === canvas) return;
            if (window.mainCanvases[id] && window.mainCanvases[id].canvas !== canvas) delete window.mainCanvases[id];
            let ctx = canvas.getContext('2d');
            const canvasRect = canvas.getBoundingClientRect();
            canvas.width = Math.max(1, Math.round(canvasRect.width || canvas.clientWidth || canvas.parentElement.clientWidth || 750));
            canvas.height = Math.max(1, Math.round(canvasRect.height || canvas.clientHeight || canvas.parentElement.clientHeight || 250)); 
            ctx.lineCap = 'round'; ctx.lineJoin = 'round';
            
            let objects = []; let currentObj = null; let draggingObj = null; let action = null; 
            let history = []; let historyIndex = -1;
            let dragStartX = 0, dragStartY = 0; let dragStartDist = 1, initialScale = 1; let dragStartAngle = 0, initialAngle = 0; let isDrawing = false;

            function cloneObjects() { return JSON.parse(JSON.stringify(objects)); }
            function restoreObjects(snapshot) { objects.length = 0; snapshot.forEach(obj => objects.push(JSON.parse(JSON.stringify(obj)))); draggingObj = null; currentObj = null; action = null; renderAll(); }
            function saveHistory() { history = history.slice(0, historyIndex + 1); history.push(cloneObjects()); if (history.length > 80) history.shift(); historyIndex = history.length - 1; }
            function undo() { if (historyIndex <= 0) return; historyIndex--; restoreObjects(history[historyIndex]); }
            function redo() { if (historyIndex >= history.length - 1) return; historyIndex++; restoreObjects(history[historyIndex]); }

            function getRawBounds(obj) {
                let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
                if (obj.tool === 'pen' || obj.tool === 'highlighter' || obj.tool === 'eraser') {
                    if(!obj.points || obj.points.length === 0) return {minX:0, minY:0, maxX:0, maxY:0};
                    obj.points.forEach(p => { minX = Math.min(minX, p.x); minY = Math.min(minY, p.y); maxX = Math.max(maxX, p.x); maxY = Math.max(maxY, p.y); });
                } else {
                    let sx = obj.sx, sy = obj.sy, ex = obj.ex, ey = obj.ey; let dx = ex - sx, dy = ey - sy; let rx = Math.abs(dx), ry = Math.abs(dy); let r = Math.sqrt(dx*dx + dy*dy);
                    if (obj.tool === 'line' || obj.tool === 'vector') { minX = Math.min(sx, ex); maxX = Math.max(sx, ex); minY = Math.min(sy, ey); maxY = Math.max(sy, ey); }
                    else if (obj.tool === 'circle' || obj.tool === 'sphere') { minX = sx - r; maxX = sx + r; minY = sy - r; maxY = sy + r; }
                    else if (obj.tool === 'triangle') { minX = Math.min(sx, ex, sx + dx/2); maxX = Math.max(sx, ex, sx + dx/2); minY = Math.min(sy, ey); maxY = Math.max(sy, ey); }
                    else if (obj.tool === 'cylinder' || obj.tool === 'cone') { minX = sx - rx; maxX = sx + rx; let h = ry * 0.2; minY = Math.min(sy - h, ey - h); maxY = Math.max(sy + h, ey + h); }
                }
                let pad = obj.tool === 'highlighter' ? Math.max(12, (parseFloat(obj.size) || 3) * 4) / 2 : (parseFloat(obj.size) || 3); return { minX: minX - pad, minY: minY - pad, maxX: maxX + pad, maxY: maxY + pad };
            }
            
            function drawSmoothFreehandPath(targetCtx, points) {
                if (!points || points.length === 0) return;
                targetCtx.beginPath();
                targetCtx.moveTo(points[0].x, points[0].y);
                if (points.length === 1) {
                    targetCtx.lineTo(points[0].x + 0.01, points[0].y + 0.01);
                } else if (points.length === 2) {
                    targetCtx.lineTo(points[1].x, points[1].y);
                } else {
                    for (let i = 1; i < points.length - 1; i++) {
                        const midX = (points[i].x + points[i + 1].x) / 2;
                        const midY = (points[i].y + points[i + 1].y) / 2;
                        targetCtx.quadraticCurveTo(points[i].x, points[i].y, midX, midY);
                    }
                    const last = points[points.length - 1];
                    targetCtx.lineTo(last.x, last.y);
                }
                targetCtx.stroke();
            }

            function drawObj(ctx, obj, isSelected) {
                ctx.save(); let cx = obj.cx || 0; let cy = obj.cy || 0; let s = obj.scale || 1;
                ctx.translate((obj.x || 0) + cx, (obj.y || 0) + cy); ctx.rotate(obj.angle || 0); ctx.scale(s, s); ctx.translate(-cx, -cy);
                ctx.strokeStyle = obj.color; ctx.lineWidth = obj.size;
                ctx.globalAlpha = obj.tool === 'highlighter' ? 0.28 : 1;
                if (obj.tool === 'highlighter') ctx.lineWidth = Math.max(12, (parseFloat(obj.size) || 3) * 4);
                if (obj.tool === 'pen' || obj.tool === 'highlighter' || obj.tool === 'eraser') {
                    ctx.globalCompositeOperation = obj.tool === 'eraser' ? 'destination-out' : 'source-over';
                    if(obj.tool === 'eraser') ctx.lineWidth = obj.size * 3;
                    ctx.lineCap = 'round';
                    ctx.lineJoin = 'round';
                    drawSmoothFreehandPath(ctx, obj.points || []);
                } else {
                    ctx.globalCompositeOperation = 'source-over'; ctx.beginPath();
                    let sx = obj.sx, sy = obj.sy, ex = obj.ex, ey = obj.ey; let dx = ex - sx, dy = ey - sy; let rx = Math.abs(dx), ry = Math.abs(dy); let r = Math.sqrt(dx*dx + dy*dy);
                    if (obj.tool === 'line' || obj.tool === 'vector') { 
                        ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke(); 
                        if(obj.tool === 'vector') { 
                            let angle = Math.atan2(ey - sy, ex - sx); 
                            let headlen = 10 + (parseFloat(obj.size)||3); 
                            ctx.beginPath(); 
                            ctx.moveTo(ex, ey); 
                            ctx.lineTo(ex - headlen * Math.cos(angle - Math.PI / 6), ey - headlen * Math.sin(angle - Math.PI / 6)); 
                            ctx.moveTo(ex, ey); 
                            ctx.lineTo(ex - headlen * Math.cos(angle + Math.PI / 6), ey - headlen * Math.sin(angle + Math.PI / 6)); 
                            ctx.stroke(); 
                        } 
                    }
                    else if (obj.tool === 'circle') { ctx.arc(sx, sy, r, 0, 2 * Math.PI); ctx.stroke(); }
                    else if (obj.tool === 'triangle') { ctx.moveTo(sx + dx/2, sy); ctx.lineTo(sx, ey); ctx.lineTo(ex, ey); ctx.closePath(); ctx.stroke(); }
                    else if (obj.tool === 'cylinder') { let w = rx, h = ry * 0.2; if(w>0 && h>0){ctx.ellipse(sx, sy, w, h, 0, 0, 2*Math.PI); ctx.moveTo(sx - w, sy); ctx.lineTo(sx - w, ey); ctx.moveTo(sx + w, sy); ctx.lineTo(sx + w, ey); ctx.stroke(); ctx.beginPath(); ctx.ellipse(sx, ey, w, h, 0, 0, Math.PI); ctx.stroke(); ctx.beginPath(); ctx.setLineDash([5, 5]); ctx.ellipse(sx, ey, w, h, 0, Math.PI, 2*Math.PI); ctx.stroke(); ctx.setLineDash([]);} }
                    else if (obj.tool === 'cone') { let w = rx, h = ry * 0.2; if(w>0 && h>0){ctx.moveTo(sx, sy); ctx.lineTo(sx - w, ey); ctx.moveTo(sx, sy); ctx.lineTo(sx + w, ey); ctx.stroke(); ctx.beginPath(); ctx.ellipse(sx, ey, w, h, 0, 0, Math.PI); ctx.stroke(); ctx.beginPath(); ctx.setLineDash([5, 5]); ctx.ellipse(sx, ey, w, h, 0, Math.PI, 2*Math.PI); ctx.stroke(); ctx.setLineDash([]);} }
                    else if (obj.tool === 'sphere') { ctx.arc(sx, sy, r, 0, 2 * Math.PI); ctx.stroke(); if(r>0){ctx.beginPath(); ctx.ellipse(sx, sy, r, r*0.3, 0, 0, Math.PI); ctx.stroke(); ctx.beginPath(); ctx.setLineDash([5, 5]); ctx.ellipse(sx, sy, r, r*0.3, 0, Math.PI, 2*Math.PI); ctx.stroke(); ctx.setLineDash([]);} }
                }
                ctx.globalAlpha = 1;
                ctx.globalCompositeOperation = 'source-over';
                if (isSelected) {
                    let b = getRawBounds(obj); ctx.strokeStyle = 'rgba(255, 140, 0, 0.7)'; ctx.lineWidth = 1.5 / s; ctx.setLineDash([5 / s, 5 / s]); ctx.strokeRect(b.minX - 5, b.minY - 5, b.maxX - b.minX + 10, b.maxY - b.minY + 10); ctx.setLineDash([]);
                    let rotHX = (b.minX + b.maxX)/2; let rotHY = b.minY - 25; ctx.beginPath(); ctx.moveTo(rotHX, b.minY - 5); ctx.lineTo(rotHX, rotHY); ctx.stroke(); ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(rotHX, rotHY, 5 / s, 0, Math.PI*2); ctx.fill(); ctx.stroke();
                    let scaleHX = b.maxX + 5; let scaleHY = b.maxY + 5; let hSize = 10 / s; ctx.fillStyle = '#ff8c00'; ctx.fillRect(scaleHX - hSize/2, scaleHY - hSize/2, hSize, hSize);
                }
                ctx.restore();
            }

            function getLocalPos(p, obj) { let cx = obj.cx || 0, cy = obj.cy || 0; let tx = (obj.x || 0) + cx, ty = (obj.y || 0) + cy; let nx = p.x - tx, ny = p.y - ty; let angle = -(obj.angle || 0); let rx = nx * Math.cos(angle) - ny * Math.sin(angle); let ry = nx * Math.sin(angle) + ny * Math.cos(angle); let scale = obj.scale || 1; return {x: (rx / scale) + cx, y: (ry / scale) + cy}; }
            function renderAll() { ctx.clearRect(0, 0, canvas.width, canvas.height); objects.forEach(obj => drawObj(ctx, obj, draggingObj === obj)); if (currentObj) drawObj(ctx, currentObj, false); }
            function getPos(e) {
                const rect = canvas.getBoundingClientRect();
                let x = e.clientX, y = e.clientY;
                if (e.touches && e.touches.length > 0) { x = e.touches[0].clientX; y = e.touches[0].clientY; }
                const scaleX = rect.width ? canvas.width / rect.width : 1;
                const scaleY = rect.height ? canvas.height / rect.height : 1;
                return { x: (x - rect.left) * scaleX, y: (y - rect.top) * scaleY };
            }

            function appendFreehandPoint(obj, p, drawIncrementally = true) {
                if (!obj || !obj.points) return;
                const pts = obj.points;
                const prev = pts[pts.length - 1];
                if (prev && Math.hypot(p.x - prev.x, p.y - prev.y) < 0.45) return;
                pts.push(p);
                if (!drawIncrementally || pts.length < 2) return;

                ctx.save();
                ctx.strokeStyle = obj.color;
                ctx.lineWidth = obj.tool === 'highlighter' ? Math.max(12, (parseFloat(obj.size) || 3) * 4) : (obj.tool === 'eraser' ? (parseFloat(obj.size) || 3) * 3 : (parseFloat(obj.size) || 3));
                ctx.globalAlpha = obj.tool === 'highlighter' ? 0.28 : 1;
                ctx.globalCompositeOperation = obj.tool === 'eraser' ? 'destination-out' : 'source-over';
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';
                ctx.beginPath();

                if (pts.length === 2) {
                    const a = pts[0], b = pts[1];
                    ctx.moveTo(a.x, a.y);
                    ctx.lineTo((a.x + b.x) / 2, (a.y + b.y) / 2);
                } else {
                    const a = pts[pts.length - 3];
                    const b = pts[pts.length - 2];
                    const c = pts[pts.length - 1];
                    const startX = (a.x + b.x) / 2;
                    const startY = (a.y + b.y) / 2;
                    const endX = (b.x + c.x) / 2;
                    const endY = (b.y + c.y) / 2;
                    ctx.moveTo(startX, startY);
                    ctx.quadraticCurveTo(b.x, b.y, endX, endY);
                }
                ctx.stroke();
                ctx.restore();
            }

            function startDraw(e) {
                isDrawing = true; let p = getPos(e); 
                let tool = document.getElementById('tool-' + id).value; let color = document.getElementById('color-' + id).value; let size = document.getElementById('size-' + id).value;
                if (tool === 'zoom') {
                    isDrawing = false;
                    const card = document.getElementById('draft-diagram-card-' + id);
                    const visual = card && card.querySelector('svg,img,picture,canvas');
                    if (visual) {
                        const point = (e.touches && e.touches[0]) ? e.touches[0] : e;
                        const r = visual.getBoundingClientRect();
                        if (point.clientX >= r.left && point.clientX <= r.right && point.clientY >= r.top && point.clientY <= r.bottom) window.openDraftVisualZoom(visual);
                    }
                    if (e.cancelable) e.preventDefault();
                    return;
                }
                if (tool === 'pointer') {
                    let hitHandle = false;
                    if (draggingObj) {
                        let b = getRawBounds(draggingObj); let lp = getLocalPos(p, draggingObj); let hr = 10 / (draggingObj.scale || 1); 
                        if (Math.abs(lp.x - (b.maxX + 5)) < hr && Math.abs(lp.y - (b.maxY + 5)) < hr) { action = 'scale'; let tx = (draggingObj.x||0) + (draggingObj.cx||0); let ty = (draggingObj.y||0) + (draggingObj.cy||0); dragStartDist = Math.hypot(p.x - tx, p.y - ty); initialScale = draggingObj.scale || 1; hitHandle = true; }
                        if (!hitHandle && Math.abs(lp.x - ((b.minX + b.maxX)/2)) < hr && Math.abs(lp.y - (b.minY - 25)) < hr) { action = 'rotate'; initialAngle = draggingObj.angle || 0; let tx = (draggingObj.x||0) + (draggingObj.cx||0); let ty = (draggingObj.y||0) + (draggingObj.cy||0); dragStartAngle = Math.atan2(p.y - ty, p.x - tx); hitHandle = true; }
                        if (!hitHandle && lp.x >= b.minX - 5 && lp.x <= b.maxX + 5 && lp.y >= b.minY - 5 && lp.y <= b.maxY + 5) { action = 'move'; dragStartX = p.x; dragStartY = p.y; hitHandle = true; }
                    }
                    if (!hitHandle) { draggingObj = null; action = null; for (let i = objects.length - 1; i >= 0; i--) { if (objects[i].tool === 'eraser') continue; let lp = getLocalPos(p, objects[i]); let b = getRawBounds(objects[i]); if (lp.x >= b.minX && lp.x <= b.maxX && lp.y >= b.minY && lp.y <= b.maxY) { draggingObj = objects[i]; action = 'move'; dragStartX = p.x; dragStartY = p.y; break; } } }
                    renderAll();
                } else { currentObj = { tool: tool, color: color, size: size, x: 0, y: 0, scale: 1, angle: 0 }; if (tool === 'pen' || tool === 'highlighter' || tool === 'eraser') { currentObj.points = [p]; } else { currentObj.sx = p.x; currentObj.sy = p.y; currentObj.ex = p.x; currentObj.ey = p.y; } }
                if (e.cancelable) e.preventDefault();
            }

            function draw(e) {
                if (!isDrawing) return;
                if (e.cancelable) e.preventDefault();
                let p = getPos(e);
                if (document.getElementById('tool-' + id).value === 'pointer' && draggingObj && action) {
                    if (action === 'move') { draggingObj.x = (draggingObj.x || 0) + (p.x - dragStartX); draggingObj.y = (draggingObj.y || 0) + (p.y - dragStartY); dragStartX = p.x; dragStartY = p.y; }
                    else if (action === 'scale') { let tx = (draggingObj.x||0) + (draggingObj.cx||0); let ty = (draggingObj.y||0) + (draggingObj.cy||0); let currentDist = Math.hypot(p.x - tx, p.y - ty); draggingObj.scale = Math.max(0.1, initialScale * (currentDist / dragStartDist)); }
                    else if (action === 'rotate') { let tx = (draggingObj.x||0) + (draggingObj.cx||0); let ty = (draggingObj.y||0) + (draggingObj.cy||0); let currentAngle = Math.atan2(p.y - ty, p.x - tx); draggingObj.angle = initialAngle + (currentAngle - dragStartAngle); }
                    renderAll();
                } else if (currentObj) {
                    if (currentObj.tool === 'pen' || currentObj.tool === 'highlighter' || currentObj.tool === 'eraser') {
                        const samples = (typeof e.getCoalescedEvents === 'function') ? e.getCoalescedEvents() : [];
                        if (samples && samples.length) {
                            samples.forEach(sample => appendFreehandPoint(currentObj, getPos(sample), true));
                        } else {
                            appendFreehandPoint(currentObj, p, true);
                        }
                    } else {
                        currentObj.ex = p.x;
                        currentObj.ey = p.y;
                        renderAll();
                    }
                }
            }

            function stopDraw(e) {
                if(!isDrawing) return;
                if (currentObj && e && (currentObj.tool === 'pen' || currentObj.tool === 'highlighter' || currentObj.tool === 'eraser')) {
                    const hasPointerCoords = Number.isFinite(e.clientX) && Number.isFinite(e.clientY);
                    const hasTouchCoords = e.changedTouches && e.changedTouches.length > 0;
                    if (hasPointerCoords || hasTouchCoords) {
                        const sourceEvent = hasPointerCoords ? e : e.changedTouches[0];
                        const finalPoint = getPos(sourceEvent);
                        appendFreehandPoint(currentObj, finalPoint, true);
                    }
                }
                isDrawing = false;
                let changed = false;
                if (currentObj) {
                    let b = getRawBounds(currentObj);
                    currentObj.cx = (b.minX + b.maxX) / 2;
                    currentObj.cy = (b.minY + b.maxY) / 2;
                    objects.push(currentObj);
                    currentObj = null;
                    changed = true;
                } else if (draggingObj && action) { changed = true; }
                action = null;
                if (changed) saveHistory();
                renderAll();
            }

            if (window.PointerEvent) {
                canvas.addEventListener('pointerdown', function(e) {
                    if (canvas.setPointerCapture && e.pointerId !== undefined) {
                        try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
                    }
                    startDraw(e);
                });
                canvas.addEventListener('pointermove', draw);
                canvas.addEventListener('pointerup', stopDraw);
                canvas.addEventListener('pointercancel', stopDraw);
            } else {
                canvas.addEventListener('mousedown', startDraw);
                canvas.addEventListener('mousemove', draw);
                window.addEventListener('mouseup', stopDraw);
                canvas.addEventListener('touchstart', startDraw, {passive: false});
                canvas.addEventListener('touchmove', draw, {passive: false});
                window.addEventListener('touchend', stopDraw);
            }
            
            window.mainCanvases[id] = { canvas, ctx, objects, renderAll, undo, redo, saveHistory };
            saveHistory();
        };
        window.clearCanvas = function(id) { if (window.mainCanvases[id]) { window.mainCanvases[id].objects.length = 0; window.mainCanvases[id].saveHistory(); window.mainCanvases[id].renderAll(); } };
        window.undoCanvas = function(id) { if (window.mainCanvases[id] && window.mainCanvases[id].undo) window.mainCanvases[id].undo(); };
        window.redoCanvas = function(id) { if (window.mainCanvases[id] && window.mainCanvases[id].redo) window.mainCanvases[id].redo(); };
        window.setTool = function(id, tool) {
            let t = document.getElementById('tool-' + id); if(t) t.value = tool; 
            let sel = document.getElementById('tool-select-' + id); if(sel && (tool === 'pen' || tool === 'highlighter' || tool === 'eraser' || tool === 'pointer' || tool === 'zoom')) sel.value = "";
            let canvas = document.getElementById('canvas-' + id);
            if(canvas) {
                if (tool === 'eraser') { canvas.style.cursor = "url('data:image/svg+xml;utf8,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%2224%22 height=%2224%22><text y=%2220%22 font-size=%2220%22>🧽</text></svg>') 0 20, auto"; } 
                else if (tool === 'pointer') { canvas.style.cursor = 'move'; } else if (tool === 'zoom') { canvas.style.cursor = 'zoom-in'; } else { canvas.style.cursor = 'crosshair'; }
            }
        };
    `;

