    function egeHydrateExportImages(sources, prefix) {
        const urls = {};
        function resolve(value) {
            return value.replace(/data:image\/gif;base64,R0lGODlhAQABAIAAAAAAAP\/\/\/yH5BAEAAAAALAAAAAABAAEAAAIBRAA7#ege-image-(\d+)/g, (match, id) => {
                if (!sources[id]) return match;
                if (!urls[id]) {
                    const source = sources[id], comma = source.indexOf(',');
                    const binary = atob(source.slice(comma + 1));
                    const bytes = new Uint8Array(binary.length);
                    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
                    urls[id] = URL.createObjectURL(new Blob([bytes], {type: source.slice(5, source.indexOf(';'))}));
                }
                return urls[id];
            });
        }
        function update(element) {
            if (element.nodeType !== 1) return;
            if (element.tagName === 'STYLE' && element.textContent.includes(prefix)) {
                element.textContent = resolve(element.textContent);
            }
            for (const attribute of Array.from(element.attributes)) {
                if (attribute.value.includes(prefix)) {
                    const value = resolve(attribute.value);
                    if (value !== attribute.value) element.setAttribute(attribute.name, value);
                }
            }
        }
        function hydrate(root) {
            update(root);
            if (root.querySelectorAll) root.querySelectorAll('img, image, source, [style], style').forEach(update);
        }
        new MutationObserver(records => {
            for (const record of records) {
                if (record.type === 'attributes') update(record.target);
                else record.addedNodes.forEach(hydrate);
            }
        }).observe(document.documentElement, {
            childList: true, subtree: true, attributes: true,
            attributeFilter: ['src', 'srcset', 'href', 'xlink:href', 'style']
        });
        hydrate(document.documentElement);
        document.addEventListener('DOMContentLoaded', () => hydrate(document.documentElement), {once: true});
    }

    // Include visible figures and figures inside encoded breakdowns in the saved HTML.
    async function egeEmbedExportImages(html) {
        const saved = new DOMParser().parseFromString(html, 'text/html');
        const sourceBase = document.baseURI;
        const pending = new Map();
        const byData = new Map();
        const sources = {};
        const prefix = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7#ege-image-';
        async function sourceData(source) {
            if (/^data:image\//i.test(source)) return source;
            const url = new URL(source, sourceBase).href;
            if (!pending.has(url)) pending.set(url, (async () => {
                const controller = new AbortController();
                const timeout = setTimeout(() => controller.abort(), 20000);
                try {
                    const response = await fetch(url, {signal: controller.signal});
                    if (!response.ok) throw new Error('Не удалось загрузить изображение');
                    const blob = await response.blob();
                    if (!/^image\//i.test(blob.type)) throw new Error('Вместо изображения получен другой файл');
                    return await new Promise((resolve, reject) => {
                        const reader = new FileReader();
                        reader.onload = () => resolve(reader.result);
                        reader.onerror = reject;
                        reader.readAsDataURL(blob);
                    });
                } finally { clearTimeout(timeout); }
            })());
            return pending.get(url);
        }
        async function embed(root) {
            await Promise.all(Array.from(root.querySelectorAll('img, svg image')).map(async image => {
                const attribute = image.hasAttribute('src') ? 'src' : image.hasAttribute('href') ? 'href' : 'xlink:href';
                const source = image.getAttribute(attribute);
                if (!source || source.startsWith('#')) return;
                const data = await sourceData(source);
                if (!byData.has(data)) {
                    const id = byData.size;
                    byData.set(data, id);
                    sources[id] = data;
                }
                image.setAttribute(attribute, prefix + byData.get(data));
            }));
        }
        await Promise.all(Array.from(saved.querySelectorAll('[id^="theory-data-"], [id^="analogs-data-"]')).map(async element => {
            const fragment = document.createElement('template');
            fragment.innerHTML = decodeURIComponent(element.textContent);
            await embed(fragment.content);
            element.textContent = encodeURIComponent(fragment.innerHTML);
        }));
        await embed(saved);
        if (byData.size) {
            const bootstrap = saved.createElement('script');
            bootstrap.setAttribute('data-ege-shared-images', '');
            bootstrap.textContent = '(' + egeHydrateExportImages.toString() + ')(' + JSON.stringify(sources) + ',' + JSON.stringify(prefix) + ');';
            saved.head.prepend(bootstrap);
        }
        return '<!DOCTYPE html>\n' + saved.documentElement.outerHTML;
    }

    async function downloadStudentHTML() {
        if (!currentInteractiveHTML) { alert("Сначала сгенерируйте вариант!"); return; }
        const button = document.querySelector('button[onclick="downloadStudentHTML()"]');
        const buttonText = button && button.textContent;
        if (button && button.disabled) return;
        if (button) { button.disabled = true; button.textContent = 'Подготавливаем вариант…'; }
        try {
        const variantTitle = getCurrentVariantTitle();
        let theme = document.getElementById("theme-select").value;
        let customBg = getSelectedCustomBg();
        let timerValue = document.getElementById("timer-input").value;
        let customBgRule = '';
        if (theme === 'custom' && customBg) { customBgRule = `.bg-custom { background: #f4f7f6 url('${customBg}') center top / cover no-repeat fixed !important; }`; theme = 'custom'; }

        let teacherName = document.getElementById('teacher-name').value.trim();
        let sig = "";
        if (document.getElementById('toggle-signature').checked && teacherName !== '') {
            let verb = (document.getElementById('teacher-gender').value === 'male') ? 'подготовил' : 'подготовила';
            sig = `<div style="text-align:center;font-family:'Caveat';font-size:26px;color:#003399;margin-top:-10px;margin-bottom:25px;">Вариант ${verb}: ${teacherName}</div>`;
        }
        let showCorrectOnError = document.getElementById('toggle-show-correct').checked;

        // Кнопки замены нужны только в генераторе. В скачанный ученический
        // вариант кнопку не переносим.
        const studentInteractiveHTML = currentInteractiveHTML
            .replace(/<div class="ege-replace-bar">[\s\S]*?<\/div>/g, '').replace(
            /<button\b[^>]*class=["'][^"']*\brandom-replace-btn\b[^"']*["'][^>]*>[\s\S]*?<\/button>/gi,
            ''
        );
        
        const mathConfig = {"tex": {"inlineMath": [["$", "$"], ["\\(", "\\)"]], "processEscapes": true, "macros": {"tg": "\\operatorname{tg}", "ctg": "\\operatorname{ctg}", "arctg": "\\operatorname{arctg}", "arcctg": "\\operatorname{arcctg}"}}, "chtml": {"adaptiveCSS": false}};
        let html = `<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Интерактив</title>
    <base href="https://svetlana18011991.github.io/generator11prof/">
    <link href="https://fonts.googleapis.com/css2?family=Caveat:wght@600&display=swap" rel="stylesheet">
    <script>window.MathJax=${JSON.stringify(mathConfig)};${window.SCRIPT_END}
    ${egeOfflineMathJaxHTML()}
    <style>
        body{font-family:sans-serif;margin:0;padding:0;background:#f4f7f6;color:#333;}
        .theme-wrapper{min-height:100vh;padding:40px 20px;}
        .bg-winter{background:#f4f7f6 url('data:image/jpeg;base64,') center top/cover no-repeat fixed;}
        .bg-spring{background:#f6f9f2 url('data:image/jpeg;base64,') center top/cover no-repeat fixed;}
        .bg-summer{background:#f4f7f6 url('data:image/jpeg;base64,') center top/cover no-repeat fixed;}
        .bg-autumn{background:#f4f7f6 url('data:image/jpeg;base64,') center top/cover no-repeat fixed;}
        ${customBgRule}
        .paper{max-width:800px;margin:0 auto;background:rgba(255,255,255,0.95);padding:40px;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,0.1);}
        .timer-box { position: sticky; top: 20px; float: right; background: #fff; border: 2px solid #ff8c00; color: #ff8c00; padding: 10px 20px; border-radius: 8px; font-size: 1.2em; font-weight: bold; box-shadow: 0 4px 10px rgba(0,0,0,0.1); z-index: 100; }
        .modal-overlay { display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.8); z-index: 1000; align-items: center; justify-content: center; backdrop-filter: blur(5px); }
        .modal-box { background: #fff; max-width: 800px; width: 90%; max-height: 90vh; overflow-y: auto; border-radius: 12px; border: 2px solid #ff8c00; box-shadow: 0 10px 30px rgba(0,0,0,0.3); padding: 30px; position: relative; text-align: left; font-size: 18px;}
        .close-btn { position: absolute; top: 15px; right: 20px; font-size: 32px; line-height: 1; cursor: pointer; color: #888; transition: 0.2s; }
        .close-btn:hover { color: #ff8c00; }
        .btn-settings { background: #333; color: #aaa; border: 1px solid #555; padding: 5px 10px; border-radius: 4px; cursor: pointer; font-size: 0.85em; transition: 0.2s; }
        .btn-settings:hover { background: #444; color: #fff; }
        .answer-feedback { border-radius: 6px; padding: 6px 10px; }
        .answer-feedback.correct { display: inline-block !important; color: #1b5e20; background: #e8f5e9; border: 1px solid #4CAF50; }
        .answer-feedback.wrong { display: inline-block !important; color: #b71c1c; background: #ffebee; border: 1px solid #f44336; }
        .answer-feedback.empty { display: inline-block !important; color: #555; background: #f5f5f5; border: 1px solid #9e9e9e; }
        svg { overflow: visible; }
    </style>
</head>
<body>
    <div class="theme-wrapper bg-${theme}">
        <div class="paper">
            <div class="timer-box" id="timer-display">⏱ 00:00</div>
            <h1 style="text-align: center; color: #003399; border-bottom: 2px solid #ff8c00; padding-bottom: 15px; margin-top:0;">${variantTitle}</h1>
            ${sig}
            ${studentInteractiveHTML}
            <button id="btn-check" onclick="checkAll()" style="display:block; width:100%; padding:15px; font-size:18px; font-weight:bold; background:#ff8c00; color:#fff; border:none; border-radius:8px; cursor:pointer; margin-top:30px; transition:0.3s;">ПОДВЕСТИ ИТОГИ</button>
            <div id="res-box" style="display:none; text-align:center; margin-top:30px; padding:20px; background:rgba(255,255,255,0.9); border:2px dashed #003399; border-radius:8px; font-size:1.2em; font-weight:bold;"></div>
        </div>
    </div>

    <div id="modal-overlay" class="modal-overlay" onclick="if(event.target===this) document.getElementById('modal-overlay').style.display='none'">
        <div class="modal-box">
            <div class="close-btn" onclick="document.getElementById('modal-overlay').style.display='none'">&times;</div>
            <div id="modal-content-box"></div>
        </div>
    </div>

    <script>
        ${window.CANVAS_LOGIC_SCRIPT}
        const SHOW_CORRECT_ON_ERROR = ${showCorrectOnError};
        let timerInterval; let timeLimit = ${timerValue} * 60; let timeSpent = 0; let isCountdown = timeLimit > 0;

        function setFeedback(taskNum, status, correctAns) {
            let feedback = document.getElementById('feedback-' + taskNum);
            if (!feedback) return;
            feedback.className = 'answer-feedback';
            feedback.style.display = 'none';
            feedback.innerHTML = '';
            if (status === 'correct') {
                feedback.classList.add('correct');
                feedback.innerHTML = '✅ Верно';
            } else if (status === 'wrong') {
                feedback.classList.add('wrong');
                feedback.innerHTML = SHOW_CORRECT_ON_ERROR ? '❌ Неверно. Верный ответ: <b>' + correctAns + '</b>' : '❌ Неверно';
            } else if (status === 'empty') {
                feedback.classList.add('empty');
                feedback.innerHTML = SHOW_CORRECT_ON_ERROR ? 'Не решено. Верный ответ: <b>' + correctAns + '</b>' : 'Не решено';
            }
        }

        function getTaskNumFromInput(input) {
            let match = input.id.match(/ans-interactive-(\d+)/);
            return match ? match[1] : '';
        }
        function updateTimerUI(sec) {
            let m = Math.floor(sec / 60).toString().padStart(2, '0');
            let s = (sec % 60).toString().padStart(2, '0');
            document.getElementById('timer-display').innerText = (isCountdown ? '⏳ Осталось: ' : '⏱ Прошло: ') + m + ':' + s;
        }
        window.onload = function() {
            updateTimerUI(isCountdown ? timeLimit : timeSpent);
            timerInterval = setInterval(() => {
                if (isCountdown) {
                    timeLimit--; updateTimerUI(timeLimit);
                    if (timeLimit <= 0) { clearInterval(timerInterval); alert('Время вышло! Итоги подводятся автоматически.'); checkAll(); }
                } else { timeSpent++; updateTimerUI(timeSpent); }
            }, 1000);
        };
        
        // --- ФУНКЦИЯ ОДИНОЧНОЙ (МГНОВЕННОЙ) ПРОВЕРКИ ---
        function checkSingle(btn, taskNum, correctAns) {
            let input = document.getElementById('ans-interactive-' + taskNum);
            if (!input) return;
            let u = input.value.trim().replace(',', '.');
            if (u === '') return; // не проверяем, если пусто
            
            let r = String(correctAns).trim().replace(',', '.').replace(/\u2212/g, '-').replace(/\s+/g, '');
            if (u === r) {
                input.style.background = '#e8f5e9'; input.style.borderColor = '#4CAF50'; input.style.color = '#1b5e20';
                setFeedback(taskNum, 'correct', correctAns);
            } else {
                input.style.background = '#ffebee'; input.style.borderColor = '#f44336'; input.style.color = '#b71c1c';
                setFeedback(taskNum, 'wrong', correctAns);
            }
            input.readOnly = true;
            btn.style.display = 'none'; // Прячем галочку после проверки
            
            // Если разбор предусмотрен - сразу показываем его
            let helpBtn = document.getElementById('btn-help-' + taskNum);
            if (helpBtn) helpBtn.style.display = 'inline-flex';
        }

        // --- ПОДВЕДЕНИЕ ОБЩИХ ИТОГОВ ---
        function checkAll() {
            if (timerInterval) clearInterval(timerInterval);
            let c = 0, ic = 0, e = 0;
            let taskStatistics = [];
            document.querySelectorAll('.ans-box').forEach(input => {
                let studentAnswer = input.value.trim();
                let u = studentAnswer.replace(',', '.');
                let r = String(input.getAttribute('data-ans')).trim().replace(',', '.').replace(/\u2212/g, '-').replace(/\s+/g, '');

                let taskNum = getTaskNumFromInput(input);
                let status = '';
                if(u === '') { 
                    e++; status = 'empty'; input.style.background = '#f5f5f5'; input.style.borderColor = '#9e9e9e'; 
                    setFeedback(taskNum, 'empty', r);
                } else if(u === r) { 
                    c++; status = 'correct'; input.style.background = '#e8f5e9'; input.style.borderColor = '#4CAF50'; input.style.color = '#1b5e20'; 
                    setFeedback(taskNum, 'correct', r);
                } else { 
                    ic++; status = 'wrong'; input.style.background = '#ffebee'; input.style.borderColor = '#f44336'; input.style.color = '#b71c1c'; 
                    setFeedback(taskNum, 'wrong', r);
                }
                taskStatistics.push({ taskNum, studentAnswer, correctAnswer: r, status });
                input.readOnly = true;
            });

            // Прячем все оставшиеся не нажатыми галочки
            document.querySelectorAll('.btn-instant').forEach(btn => btn.style.display = 'none');

            // Выводим статистику таблицей, как в презентации, но без времени выполнения
            let escapeHTML = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
            let correctHeader = SHOW_CORRECT_ON_ERROR ? '<th style="padding:12px 10px; border:1px solid #c7d2e4; text-align:center;">Верный ответ</th>' : '';
            let tableRows = '';

            taskStatistics.forEach((item, index) => {
                let statusText = item.status === 'correct' ? 'Верно' : (item.status === 'wrong' ? 'Неверно' : 'Не решено');
                let statusIcon = item.status === 'correct' ? '✅' : (item.status === 'wrong' ? '❌' : '—');
                let statusColor = item.status === 'correct' ? '#2e7d32' : (item.status === 'wrong' ? '#c62828' : '#616161');
                let statusBg = item.status === 'correct' ? '#e8f5e9' : (item.status === 'wrong' ? '#ffebee' : '#f5f5f5');
                let shownAnswer = item.studentAnswer === '' ? '<span style="color:#777;">Нет ответа</span>' : '<b>' + escapeHTML(item.studentAnswer) + '</b>';
                let correctCell = SHOW_CORRECT_ON_ERROR ? '<td style="padding:11px 10px; border:1px solid #d7deea; text-align:center; font-weight:bold; color:#003399;">' + escapeHTML(item.correctAnswer) + '</td>' : '';
                let rowBg = index % 2 === 0 ? '#ffffff' : '#f7f9fc';

                tableRows += '<tr style="background:' + rowBg + ';">' +
                    '<td style="padding:11px 10px; border:1px solid #d7deea; text-align:center; font-weight:bold; color:#003399;">' + (index + 1) + '</td>' +
                    '<td style="padding:11px 10px; border:1px solid #d7deea; text-align:center;">' + shownAnswer + '</td>' +
                    correctCell +
                    '<td style="padding:11px 10px; border:1px solid #d7deea; text-align:center;"><span style="display:inline-block; min-width:105px; padding:6px 10px; border-radius:999px; background:' + statusBg + '; color:' + statusColor + '; font-weight:bold; white-space:nowrap;">' + statusIcon + ' ' + statusText + '</span></td>' +
                '</tr>';
            });

            let detailsHTML = '<div style="margin-top:22px; text-align:left; font-size:16px; font-weight:normal;">' +
                '<div style="font-size:1.15em; font-weight:bold; color:#003399; margin-bottom:12px; text-align:center;">Статистика по заданиям</div>' +
                '<div style="overflow-x:auto; border-radius:9px; box-shadow:0 3px 12px rgba(0,0,0,0.08);">' +
                    '<table style="width:100%; min-width:560px; border-collapse:collapse; background:#fff;">' +
                        '<thead><tr style="background:#003399; color:#fff;">' +
                            '<th style="padding:12px 10px; border:1px solid #244f9a; text-align:center;">Задание</th>' +
                            '<th style="padding:12px 10px; border:1px solid #244f9a; text-align:center;">Ответ ученика</th>' +
                            correctHeader +
                            '<th style="padding:12px 10px; border:1px solid #244f9a; text-align:center;">Результат</th>' +
                        '</tr></thead>' +
                        '<tbody>' + tableRows + '</tbody>' +
                    '</table>' +
                '</div>' +
            '</div>';

            const secondPartTasks = Array.from(document.querySelectorAll('.second-part-task'));
            if (SHOW_CORRECT_ON_ERROR) {
                secondPartTasks.forEach(task => {
                    const answer = task.querySelector('.second-part-final-answer');
                    if (answer) answer.style.display = 'block';
                });
                if (window.MathJax && MathJax.typesetPromise && secondPartTasks.length) MathJax.typesetPromise(secondPartTasks).catch(()=>{});
            }
            const secondPartBadge = secondPartTasks.length ? '<div style="min-width:170px; padding:10px 14px; border-radius:8px; background:#e3f2fd; color:#003399;"><b>Вторая часть:</b> ' + secondPartTasks.length + '<br><span style="font-size:12px;font-weight:normal;">проверяется по полному решению</span></div>' : '';

            document.getElementById('res-box').innerHTML = '<div style="display:flex; justify-content:center; gap:10px; flex-wrap:wrap; margin-bottom:8px;">' +
                '<div style="min-width:120px; padding:10px 14px; border-radius:8px; background:#e8f5e9; color:#2e7d32;"><b>Верно:</b> ' + c + '</div>' +
                '<div style="min-width:120px; padding:10px 14px; border-radius:8px; background:#ffebee; color:#c62828;"><b>Неверно:</b> ' + ic + '</div>' +
                '<div style="min-width:120px; padding:10px 14px; border-radius:8px; background:#f5f5f5; color:#555;"><b>Не решено:</b> ' + e + '</div>' + secondPartBadge +
            '</div>' + detailsHTML;
            document.getElementById('res-box').style.display = 'block';
            document.getElementById('btn-check').style.display = 'none';
            
            // Открываем все доступные разборы в конце
            document.querySelectorAll('.btn-help').forEach(btn => btn.style.display = 'inline-flex');
        }
    ${window.SCRIPT_END}
</body>
</html>`;

        html = await egeEmbedExportImages(html);
        let blob = new Blob([html], {type:"text/html;charset=utf-8"});
        let a = document.createElement("a"); a.href=URL.createObjectURL(blob); a.download="Интерактивный_вариант.html"; document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(a.href);
        } catch (error) {
            console.error(error);
            alert('Не удалось включить в вариант все изображения. Проверьте соединение и повторите сохранение.');
        } finally {
            if (button) { button.disabled = false; button.textContent = buttonText; }
        }
    }

    // Выборочная сборка сохраняет прежний портретный печатный макет.
    // В режиме с полями только дополняем те же карточки клетчатыми черновиками.
    function addSelectivePrintFields(sourceHTML) {
        const host = document.createElement('div');
        host.innerHTML = sourceHTML;
        // В основной карточке формулы специально обёрнуты в nowrap-span.
        // В печати Chromium / Яндекс.Браузер иногда разносит такие формулы
        // по отдельным строкам: возвращаем стандартные inline-формулы MathJax.
        host.querySelectorAll('.task-copy span[style]').forEach(span => {
            if (span.style.whiteSpace === 'nowrap' && /\$|\\\(/.test(span.textContent || '')) {
                span.replaceWith(...Array.from(span.childNodes));
            }
        });
        // Номер в синем кружке — порядковый в подборке (11, 12...), а не номер ЕГЭ.
        // Настоящий номер берём из сгенерированных заданий и заголовка группы.
        const generated = Array.isArray(window.currentGeneratedTasks) ? window.currentGeneratedTasks : [];
        let sectionNumber = 0;
        let taskIndex = 0;
        const nodes = [...host.querySelectorAll('h3, .task-print-block')];
        nodes.forEach(node => {
            if (node.matches('h3')) {
                const match = (node.textContent || '').match(/Задани[ея]\s*[№#]?\s*(\d{1,2})(?!\d)/i);
                if (match) sectionNumber = Number(match[1]);
                return;
            }
            const task = node;
            const info = generated[taskIndex] || {};
            const match = String(info.taskTid || '').match(/(?:task)?(\d{1,2})$/i);
            const examNumber = (match ? Number(match[1]) : sectionNumber) || 0;
            const isSecondPart = Number(info.part) === 2 || info.isSecondPart === true || examNumber >= 14;
            task.dataset.egeExamNumber = String(examNumber);
            task.dataset.egeSecondPart = isSecondPart ? '1' : '0';
            const id = 'ege-selective-grid-' + taskIndex;
            const field = document.createElement('div');
            field.className = 'ege-selective-write-grid' + (isSecondPart ? ' ege-selective-long-grid' : '');
            field.setAttribute('aria-label', 'Клетчатое поле для решения задания ' + (examNumber || taskIndex + 1));
            field.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" class="ege-selective-grid-art" width="100%" height="100%" aria-hidden="true">
                <defs><pattern id="${id}" patternUnits="userSpaceOnUse" width="18.897638" height="18.897638">
                    <path d="M 18.897638 0 H 0 V 18.897638" fill="none" stroke="#b1d3ea" stroke-width="0.8"/>
                </pattern></defs>
                <rect x="0" y="0" width="100%" height="100%" fill="url(#${id})"/>
            </svg>`;
            task.appendChild(field);
            taskIndex++;
        });
        return host.innerHTML;
    }

    // Только выборочная печать С ПОЛЯМИ: осмысленное распределение карточек
    // и клетчатых черновиков по вертикальному A4. Печать без полей не затрагиваем.
    function layoutSelectiveFieldsForPrint() {
        const main = document.querySelector('main.print-page');
        if (!main || main.dataset.packed === '1') return;
        const all = Array.from(main.children);
        const firstHeader = all.find(el => el.classList.contains('print-header'));
        const units = [];
        let pending = [];
        for (const element of all) {
            if (element === firstHeader) continue;
            if (element.matches('h3') || (!element.querySelector('.task-print-block') && !element.matches('.task-print-block'))) {
                pending.push(element);
                continue;
            }
            const tasks = element.matches('.task-print-block') ? [element] : Array.from(element.querySelectorAll('.task-print-block'));
            for (const task of tasks) {
                const unit = document.createElement('div');
                unit.className = 'ege-selective-print-unit';
                pending.forEach(node => unit.appendChild(node));
                pending = [];
                unit.appendChild(task);
                const examNumber = Number(task.dataset.egeExamNumber) || 0;
                unit.dataset.taskNumber = String(examNumber);
                unit.dataset.secondPart = task.dataset.egeSecondPart === '1' ? '1' : '0';
                units.push(unit);
            }
        }
        if (pending.length) {
            const finalUnit = document.createElement('div');
            finalUnit.className = 'ege-selective-print-unit';
            pending.forEach(node => finalUnit.appendChild(node));
            units.push(finalUnit);
        }
        main.replaceChildren();
        main.dataset.packed = '1';
        const mm = 96 / 25.4;
        function makeSheet(first) {
            const sheet = document.createElement('section');
            sheet.className = 'ege-selective-sheet';
            const body = document.createElement('div');
            body.className = 'ege-selective-sheet-content';
            sheet.appendChild(body);
            main.appendChild(sheet);
            if (first && firstHeader) body.appendChild(firstHeader);
            return body;
        }
        let content = makeSheet(true);
        const minField = (grid) => grid.classList.contains('ege-selective-long-grid') ? 28 * mm : 13 * mm;
        const baseField = (grid) => grid.classList.contains('ege-selective-long-grid') ? 48 * mm : 20 * mm;
        function fields(parent) { return Array.from(parent.querySelectorAll('.ege-selective-write-grid')); }
        function fillBase(parent) {
            fields(parent).forEach(g => {g.style.height = baseField(g) + 'px';});
        }
        function usedHeight(parent) {
            const top = parent.getBoundingClientRect().top;
            const children = Array.from(parent.children);
            return children.length ? Math.max(0, Math.max(...children.map(el => el.getBoundingClientRect().bottom)) - top) : 0;
        }
        function shrinkToFit(parent) {
            const area = parent.clientHeight;
            let overflow = usedHeight(parent) - area;
            if (overflow <= 1) return true;
            const gs = fields(parent).filter(g => g.getBoundingClientRect().height > minField(g) + 1);
            const capacity = gs.reduce((sum,g) => sum + Math.max(0,g.getBoundingClientRect().height - minField(g)), 0);
            if (capacity + 1 < overflow) return false;
            for (const g of gs) {
                const old = g.getBoundingClientRect().height;
                const reduction = overflow * ((old - minField(g)) / capacity);
                g.style.height = Math.max(minField(g), old - reduction - 1) + 'px';
            }
            return usedHeight(parent) <= area + 2;
        }
        function occupySpace(parent) {
            const gs = fields(parent);
            if (!gs.length) return;
            const empty = parent.clientHeight - usedHeight(parent) - 12;
            if (empty <= 2) return;
            // Вместо полупустого листа выделяем оставшуюся площадь на решения.
            // Если сетка одна, всё свободное пространство достаётся ей.
            const extra = (empty - 2) / gs.length;
            gs.forEach(g => g.style.height = (g.getBoundingClientRect().height + extra) + 'px');
        }
        function hasPrintedUnits(parent) {
            return !!parent.querySelector('.ege-selective-print-unit');
        }
        for (let i = 0; i < units.length; i++) {
            const unit = units[i];
            const secondPart = unit.dataset.secondPart === '1';

            if (secondPart && hasPrintedUnits(content)) {
                occupySpace(content);
                content = makeSheet(false);
            }

            content.appendChild(unit);
            fillBase(unit);

            if (secondPart) {
                if (usedHeight(content) > content.clientHeight + 1) {
                    shrinkToFit(content);
                }
                occupySpace(content);
                if (i < units.length - 1) {
                    content = makeSheet(false);
                }
                continue;
            }

            if (usedHeight(content) <= content.clientHeight + 1) continue;
            if (shrinkToFit(content)) continue;
            unit.remove();
            occupySpace(content);
            content = makeSheet(false);
            content.appendChild(unit);
            fillBase(unit);
            if (usedHeight(content) > content.clientHeight + 1) {
                // Для длинного условия по возможности уменьшаем поле, но не текст.
                shrinkToFit(content);
            }
        }
        occupySpace(content);
    }

    // В печатный HTML помещаем байты контрастных графиков, а не ссылки на папку сайта.
    // Отдельный JS подключаем только при экспорте (работает даже с генератором file://).
    let egeDerivativePrintAssetsLoading = null;
    function egeLoadDerivativePrintAssets() {
        if (window.EGE_DERIVATIVE_PRINT_ASSETS) return Promise.resolve(window.EGE_DERIVATIVE_PRINT_ASSETS);
        if (!egeDerivativePrintAssetsLoading) {
            egeDerivativePrintAssetsLoading = new Promise((resolve, reject) => {
                const script = document.createElement('script');
                script.src = 'derivative_print_assets.js?v=20261109-portable1';
                script.onload = () => {
                    if (window.EGE_DERIVATIVE_PRINT_ASSETS) resolve(window.EGE_DERIVATIVE_PRINT_ASSETS);
                    else reject(new Error('Не удалось прочитать изображения для печати задания 9'));
                };
                script.onerror = () => reject(new Error('Не найден файл derivative_print_assets.js в папке генератора'));
                document.head.appendChild(script);
            }).catch(error => { egeDerivativePrintAssetsLoading = null; throw error; });
        }
        return egeDerivativePrintAssetsLoading;
    }
    // Поддержка двух исторических путей к рисункам задания 9:
    // img8/imgNN.png и img8/print/imgNN.png. Вставляем внутрь HTML,
    // чтобы файлы из папки «Загрузки» не ссылались на сайт или диск.
    async function egeEmbedDerivativePrintImages(html) {
        const imgTagWithSrc = /(<img\b[^>]*?\bsrc\s*=\s*)(["'])([^"']+)\2/gi;
        const imageFilename = /(?:^|[\\/])img8[\\/](?:print[\\/])?(img\d+\.png)(?:[?#].*)?$/i;
        const matches = [...html.matchAll(imgTagWithSrc)].filter(match => imageFilename.test(match[3]));
        if (!matches.length) return html;
        const images = await egeLoadDerivativePrintAssets();
        const missing = [];
        let changed = 0;
        const result = html.replace(imgTagWithSrc, (tag, beginning, quote, src) => {
            const match = src.match(imageFilename);
            if (!match) return tag;
            const name = match[1].toLowerCase();
            const png = images[name];
            if (typeof png !== 'string' || !png.startsWith('iVBORw0KGgo')) {
                missing.push(name);
                return tag;
            }
            changed++;
            return beginning + quote + 'data:image/png;base64,' + png + quote;
        });
        if (missing.length) throw new Error('Отсутствуют рисунки для печати: ' + [...new Set(missing)].join(', '));
        if (changed !== matches.length) throw new Error('Не все графики задания 9 встроились в печатный файл');
        const unembedded = [...result.matchAll(imgTagWithSrc)].filter(match => imageFilename.test(match[3]));
        if (unembedded.length) throw new Error('В печатном файле остались внешние рисунки задания 9');
        return result.replace('</head>', '<meta name="ege-derivative-graphics" content="embedded-v3"></head>');
    }
